-- "Monthly Subscription"), so nothing changes until the coach sets a length.
ALTER TABLE engagements ADD COLUMN IF NOT EXISTS length_months int;


-- ==================== 039_invoice_resend_receipt.sql ====================
-- 037: Invoice re-send + receipt tracking.
--
-- invoices.receipt_token   — unguessable token embedded in the client-facing
--                            "View & pay invoice" link (cover email + reminder
--                            email). Public GET /api/billing/invoices/receipt/[token]
--                            marks the invoice received and redirects to the
--                            Stripe hosted payment page. Token = credential,
--                            same pattern as actions.complete_token.
-- invoices.received_at     — set (once) when the client first opens the tracked
--                            invoice link. Surfaced as a "received" chip next to
--                            the "sent" status in the Business Center.
-- invoices.last_resent_at  — timestamp of the most recent re-send of the Stripe
--                            invoice email (audit trail on the invoice page).
--
-- All additive + nullable. Apply BEFORE deploying the resend/receipt code —
-- the send path, resend route, and reminder cron reference these columns.

ALTER TABLE invoices
  ADD COLUMN IF NOT EXISTS receipt_token text,
  ADD COLUMN IF NOT EXISTS received_at timestamptz,
  ADD COLUMN IF NOT EXISTS last_resent_at timestamptz;

CREATE UNIQUE INDEX IF NOT EXISTS invoices_receipt_token_key
  ON invoices (receipt_token)
  WHERE receipt_token IS NOT NULL;


-- ==================== 040_payment_on_file.sql ====================
-- 038_payment_on_file.sql
-- Payment on File & Charge-on-Run (build brief v3).
--
-- Stores a client's *mandate* (recorded permission to be charged off-session)
-- on a billing account, lets the coach trigger a card charge inside the billing
-- run, and adds a refund/credit/void adjustment path. Additive only — code must
-- not assume this migration is applied until Jeff confirms.
--
-- Note the brief calls this "migration 035"; the repo already has 035–037, so
-- this lands as 038 (the real next number). All three new tables get RLS with
-- no policies (service-role only, coach-scoped in code).

-- ── billing_accounts: the stored mandate ───────────────────────────────────────
ALTER TABLE billing_accounts
  ADD COLUMN IF NOT EXISTS stripe_payment_method_id    text,
  ADD COLUMN IF NOT EXISTS stripe_setup_intent_id      text,
  ADD COLUMN IF NOT EXISTS payment_method_type         text DEFAULT 'card',   -- 'card' now; 'us_bank_account' reserved (ACH, §12.2)
  ADD COLUMN IF NOT EXISTS payment_method_brand        text,
  ADD COLUMN IF NOT EXISTS payment_method_last4        text,
  ADD COLUMN IF NOT EXISTS payment_method_exp_month    int,
  ADD COLUMN IF NOT EXISTS payment_method_exp_year     int,
  -- none | active | dormant | expired | removed ('pending_verification' reserved for ACH)
  ADD COLUMN IF NOT EXISTS payment_method_status       text DEFAULT 'none',
  ADD COLUMN IF NOT EXISTS authorization_token         text,          -- unguessable, single purpose
  ADD COLUMN IF NOT EXISTS authorization_token_sent_at timestamptz,
  ADD COLUMN IF NOT EXISTS authorized_at               timestamptz,
  ADD COLUMN IF NOT EXISTS authorized_ip               text,
  ADD COLUMN IF NOT EXISTS authorized_by_email         text,
  ADD COLUMN IF NOT EXISTS authorization_text          text,          -- verbatim snapshot of language shown
  ADD COLUMN IF NOT EXISTS dormant_at                  timestamptz,
  ADD COLUMN IF NOT EXISTS reconfirmed_at              timestamptz,
  ADD COLUMN IF NOT EXISTS last_charge_at              timestamptz,   -- drives 24-month inactivity detach
  ADD COLUMN IF NOT EXISTS charge_mode                 text DEFAULT 'manual';  -- 'manual' | 'auto' (Phase B, unused)

CREATE INDEX IF NOT EXISTS billing_accounts_auth_token_idx
  ON billing_accounts(authorization_token)
  WHERE authorization_token IS NOT NULL;

-- ── invoices: charge state + adjustment denormalization ─────────────────────────
ALTER TABLE invoices
  ADD COLUMN IF NOT EXISTS collection_method       text DEFAULT 'send_invoice',   -- 'send_invoice' | 'charge_automatically'
  -- none | succeeded | failed | action_required
  ADD COLUMN IF NOT EXISTS charge_status           text DEFAULT 'none',
  ADD COLUMN IF NOT EXISTS charge_attempted_at     timestamptz,
  ADD COLUMN IF NOT EXISTS charge_attempt_count    int DEFAULT 0,
  ADD COLUMN IF NOT EXISTS charge_failure_code     text,
  ADD COLUMN IF NOT EXISTS charge_failure_message  text,
  ADD COLUMN IF NOT EXISTS charge_retry_at         timestamptz,
  ADD COLUMN IF NOT EXISTS fallback_invoice_sent_at timestamptz,      -- set by the action_required auto-fallback
  ADD COLUMN IF NOT EXISTS receipt_sent_at         timestamptz,
  ADD COLUMN IF NOT EXISTS receipt_communication_id uuid,
  ADD COLUMN IF NOT EXISTS refunded_cents          int DEFAULT 0,     -- denormalized for run UI; invoice_adjustments is source of truth
  ADD COLUMN IF NOT EXISTS credited_cents          int DEFAULT 0,
  ADD COLUMN IF NOT EXISTS voided_at               timestamptz;

CREATE INDEX IF NOT EXISTS invoices_charge_retry_idx
  ON invoices(charge_retry_at)
  WHERE charge_retry_at IS NOT NULL;

-- ── invoice_charge_attempts: the idempotency claim ──────────────────────────────
-- Insert a row BEFORE calling Stripe. The unique (invoice_id, attempt_number)
-- means a second concurrent request fails to claim and reads the first attempt's
-- state — mirrors the claim-before-send pattern in appointment_reminders.
CREATE TABLE IF NOT EXISTS invoice_charge_attempts (
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id               uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  attempt_number           int  NOT NULL,
  idempotency_key          text NOT NULL,
  status                   text NOT NULL DEFAULT 'claimed',   -- claimed | succeeded | failed
  stripe_payment_intent_id text,
  failure_code             text,
  failure_message          text,
  created_at               timestamptz NOT NULL DEFAULT now(),
  resolved_at              timestamptz,
  UNIQUE (invoice_id, attempt_number),
  UNIQUE (idempotency_key)
);

CREATE INDEX IF NOT EXISTS invoice_charge_attempts_invoice_idx
  ON invoice_charge_attempts(invoice_id);

-- ── invoice_adjustments: refund / credit / void (append-only) ───────────────────
-- Only status, failure_message, notified_at, communication_id, and the stripe id
-- fields are ever updated. Everything else is written once.
CREATE TABLE IF NOT EXISTS invoice_adjustments (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id            uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  billing_account_id    uuid NOT NULL REFERENCES billing_accounts(id) ON DELETE CASCADE,
  coach_id              uuid NOT NULL REFERENCES coaches(id) ON DELETE CASCADE,
  type                  text NOT NULL CHECK (type IN ('refund','credit_to_balance','void')),
  amount_cents          int  NOT NULL,
  reason                text NOT NULL,                 -- coach's plain-language reason, REQUIRED
  idempotency_key       text NOT NULL UNIQUE,
  stripe_credit_note_id text,
  stripe_refund_id      text,
  status                text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','succeeded','failed')),
  failure_message       text,
  created_by_email      text NOT NULL,
  notified_at           timestamptz,
  communication_id      uuid,
  created_at            timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS invoice_adjustments_invoice_idx ON invoice_adjustments(invoice_id);
CREATE INDEX IF NOT EXISTS invoice_adjustments_coach_idx   ON invoice_adjustments(coach_id, created_at DESC);

-- ── billing_authorization_events: append-only audit trail ───────────────────────
CREATE TABLE IF NOT EXISTS billing_authorization_events (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  billing_account_id uuid NOT NULL REFERENCES billing_accounts(id) ON DELETE CASCADE,
  coach_id           uuid NOT NULL REFERENCES coaches(id) ON DELETE CASCADE,
  -- link_sent | page_viewed | authorized | payment_method_updated | marked_dormant
  -- | reconfirmed | removed | expired | auto_detached | charge_disputed
  event              text NOT NULL,
  ip                 text,
  detail             jsonb,
  created_at         timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS billing_authorization_events_account_idx
  ON billing_authorization_events(billing_account_id, created_at DESC);

-- ── RLS: enabled, no policies (service-role only) ───────────────────────────────
ALTER TABLE invoice_charge_attempts       ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_adjustments           ENABLE ROW LEVEL SECURITY;
ALTER TABLE billing_authorization_events  ENABLE ROW LEVEL SECURITY;

-- A charge-failure warning isn't tied to an engagement, so relax the NOT NULL
-- on billing_run_warnings.engagement_id (migration 032 required it). Safe/additive.
ALTER TABLE billing_run_warnings ALTER COLUMN engagement_id DROP NOT NULL;

-- communications.type gains 'receipt', 'billing_authorization', 'billing_adjustment'
-- at the application layer — the column is unconstrained text, so no DDL needed.


-- ==================== 041_prep_sheet_pipeline.sql ====================
-- 039: Prep Sheet Pipeline (Generate → Review → Approve → Scheduled Send)
--
-- The guarantee: a client's prep sheet lands 48 hours before their session,
-- every time, unless the coach explicitly skips it. This table is the STATE
-- MACHINE that makes that guarantee auditable — one row per appointment, max.
--
--   draft     → generated, waiting on the coach's review/approve
--   approved  → coach approved; will dispatch at scheduled_send_at
--   sent      → delivered to the client (communication_id links the send log)
--   skipped   → coach chose to skip, no history, cancelled appt, or cutoff
--   failed    → generation or dispatch errored (surfaced in /prep)
--
-- NOTE ON THE NAME: the pre-existing `prep_sheets` table (migration 013) is a
-- SEND-LOG SNAPSHOT of interactively-sent prep emails (content jsonb + html)
-- powering the workspace "Prep sheets sent" card. That table is left untouched;
-- this pipeline gets its own name so the two never collide.
--
-- Like every table in this app: RLS ON, no public policies — reached only via
-- the service-role key (getSupabaseAdmin), coach-scoped in code (not RLS).

create table if not exists prep_sheet_pipeline (
  id uuid primary key default gen_random_uuid(),
  coach_id uuid not null references coaches(id) on delete cascade,
  client_id uuid not null references clients(id) on delete cascade,
  -- One pipeline row per appointment, enforced by the unique constraint.
  appointment_id uuid not null unique references appointments(id) on delete cascade,

  status text not null default 'draft',
    -- draft | approved | sent | skipped | failed

  subject text,
  body_html text,

  generated_at timestamptz,
  generation_model text,               -- resolved model id recorded for audit
  eligibility jsonb,                   -- what history fed the draft (counts, ids, dates)

  approved_at timestamptz,
  scheduled_send_at timestamptz,       -- the exact client-delivery moment (T-2d @ delivery_hour, clamped ≥ T-48h)

  sent_at timestamptz,
  communication_id uuid references communications(id) on delete set null,

  skipped_at timestamptz,
  skip_reason text,                    -- coach_choice | no_history | not_approved_in_time | appointment_cancelled

  error_detail text,
  skip_token text unique,              -- one-click skip from the coach review email (credential)

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- updated_at maintenance (shared trigger fn from migration 001).
create trigger prep_sheet_pipeline_set_updated_at
  before update on prep_sheet_pipeline
  for each row execute function set_updated_at();

alter table prep_sheet_pipeline enable row level security;

create index if not exists prep_sheet_pipeline_coach_status_idx
  on prep_sheet_pipeline(coach_id, status);
-- Dispatch scans approved rows whose send moment has passed; partial index keeps
-- that hot query tight.
create index if not exists prep_sheet_pipeline_scheduled_idx
  on prep_sheet_pipeline(scheduled_send_at) where status = 'approved';
create index if not exists prep_sheet_pipeline_client_idx
  on prep_sheet_pipeline(client_id);

-- Link the send log to its appointment. Pays forward into the future
-- reply-capture feature as well. Additive/nullable — existing rows unaffected.
alter table communications
  add column if not exists appointment_id uuid references appointments(id) on delete set null;

create index if not exists communications_appointment_id_idx
  on communications(appointment_id);

-- appointment_reminders.kind is free text (no CHECK) — the new coach-facing
-- claim slots 'prep_review' and 'prep_last_call' need no DDL. The existing
-- (appointment_id, kind) unique index gives each its once-only guarantee.


-- ==================== 042_organizations_and_org_id.sql ====================
-- Migration 042 — organizations + org_id big-bang  (UP)
-- Phase 1 §5.0. Introduces the tenant root and stamps every tenant row with an
-- org_id, backfilled to org #1 (theLeadershipWell). SCHEMA ONLY — no RLS is
-- enabled, no policy is added, no application behavior changes. The org_id
-- column carries a transitional DEFAULT of org #1 so existing INSERTs keep
-- working with zero code change; a later migration removes that default once
-- inserts set org_id explicitly from the request JWT (Phase 1 §5.1).
-- Reversible via 042_organizations_and_org_id_down.sql.

-- ---------------------------------------------------------------------------
-- organizations — the tenant root. RLS enabled, no policy (service-role only,
-- consistent with every other table until the strangler RLS rollout).
-- ---------------------------------------------------------------------------
create table if not exists organizations (
  id                uuid primary key default gen_random_uuid(),
  name              text not null,
  legal_entity_name text,               -- for agreements / mandates (per-tenant legal name)
  from_email        text,               -- per-org default send-from (Phase 1 §5.5)
  cc_email          text,               -- per-org default Cc
  logo_url          text,               -- per-org brand mark
  brand_color       text,               -- per-org accent
  timezone          text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

alter table organizations enable row level security;

create trigger organizations_set_updated_at
  before update on organizations
  for each row execute function set_updated_at();

-- Org #1 = theLeadershipWell (fixed id — referenced as the transitional default).
insert into organizations (id, name, legal_entity_name, from_email, cc_email)
values (
  '00000000-0000-4000-8000-000000000001',
  'theLeadershipWell',
  'theLeadershipWell',
  'jeff@jeffkholmes.com',
  'jeff@theleadershipwell.com'
)
on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- Add org_id to every tenant table: NOT NULL DEFAULT org#1 (fills existing rows
-- and any not-yet-org-aware INSERT), FK to organizations, indexed for policy
-- lookups. Idempotent.
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'actions','agenda_requests','agreement_templates','agreements',
    'appointment_reminders','appointments','billable_sessions','billing_accounts',
    'billing_authorization_events','billing_run_warnings','clients','coach_clients',
    'coach_growth_areas','coachees','coaches','communications','dashboard_layouts',
    'email_signatures','engagements','garden_edges','garden_notes',
    'growth_area_assessments','invoice_adjustments','invoice_charge_attempts',
    'invoice_lines','invoice_reminders','invoices','library_folders','note_templates',
    'notes','nudges','pdf_resources','prep_sheet_pipeline','prep_sheets',
    'session_reports','transcripts'
  ]
  loop
    execute format(
      'alter table %I add column if not exists org_id uuid not null '
      || 'default ''00000000-0000-4000-8000-000000000001'' references organizations(id)',
      t
    );
    execute format(
      'create index if not exists %I on %I (org_id)', t || '_org_id_idx', t
    );
  end loop;
end $$;

-- Safety re-assert: any row that somehow escaped the default lands on org #1.
do $$
declare t text;
begin
  foreach t in array array[
    'actions','agenda_requests','agreement_templates','agreements',
    'appointment_reminders','appointments','billable_sessions','billing_accounts',
    'billing_authorization_events','billing_run_warnings','clients','coach_clients',
    'coach_growth_areas','coachees','coaches','communications','dashboard_layouts',
    'email_signatures','engagements','garden_edges','garden_notes',
    'growth_area_assessments','invoice_adjustments','invoice_charge_attempts',
    'invoice_lines','invoice_reminders','invoices','library_folders','note_templates',
    'notes','nudges','pdf_resources','prep_sheet_pipeline','prep_sheets',
    'session_reports','transcripts'
  ]
  loop
    execute format(
      'update %I set org_id = ''00000000-0000-4000-8000-000000000001'' where org_id is null', t
    );
  end loop;
end $$;


-- ==================== 043_rls_notes_actions_select.sql ====================
-- Migration 043 — org-scoped RLS (SELECT) on notes + actions  (UP)
-- Phase 1 §5.3 group 1a — the first strangler RLS cutover.
--
-- Adds a FOR SELECT policy scoping each table to the caller's organization, read
-- from the `org_id` claim on the request-scoped JWT (lib/supabase/jwt.ts →
-- getSupabaseForClaims). SELECT-ONLY on purpose: writes still run through the
-- service-role admin client, which BYPASSES RLS, so INSERT/UPDATE/DELETE are
-- entirely unaffected by this migration. The write path (WITH CHECK + org_id on
-- inserts) lands in a later increment (§5.3 group 1b).
--
-- RLS is already ENABLED on both tables (since their original migrations) with no
-- policy — i.e. deny-by-default for any non-service-role caller. The service-role
-- key keeps bypassing these policies, so every route still on getSupabaseAdmin()
-- is unchanged. Only the authenticated-role JWT client is scoped by org.
--
-- Reversible via 043_rls_notes_actions_select_down.sql.

-- The authenticated role needs a table-level SELECT grant for the policy to have
-- anything to filter (Supabase usually grants this by default; assert it).
grant select on notes   to authenticated;
grant select on actions to authenticated;

drop policy if exists notes_org_select on notes;
create policy notes_org_select on notes
  for select
  to authenticated
  using (org_id = (auth.jwt() ->> 'org_id')::uuid);

drop policy if exists actions_org_select on actions;
create policy actions_org_select on actions
  for select
  to authenticated
  using (org_id = (auth.jwt() ->> 'org_id')::uuid);


-- ==================== 044_client_tokens.sql ====================
-- Migration 044 — client_tokens (Client Portal magic-link auth)  (UP)
-- The client-facing portal (app/portal/*) authenticates clients with single-use,
-- time-limited magic links emailed from their coach's Gmail. This table stores
-- only a SHA-256 HASH of each token (the raw token lives only in the emailed
-- link), so a DB read never yields a usable credential. Tokens are single-use
-- (used_at) and expire (expires_at). Reached only via the service-role admin
-- client (RLS enabled, no policy — consistent with the rest of the schema).
-- Reversible via 044_client_tokens_down.sql.

create table if not exists client_tokens (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null default '00000000-0000-4000-8000-000000000001'
                references organizations(id),
  client_id   uuid not null references clients(id) on delete cascade,
  token_hash  text not null,                 -- sha256(raw token); raw never stored
  purpose     text not null default 'login', -- login | (future: other portal flows)
  expires_at  timestamptz not null,
  used_at     timestamptz,                    -- set on first successful verify (single-use)
  created_at  timestamptz not null default now()
);

create index if not exists client_tokens_hash_idx    on client_tokens (token_hash);
create index if not exists client_tokens_client_idx  on client_tokens (client_id);
create index if not exists client_tokens_org_id_idx  on client_tokens (org_id);

alter table client_tokens enable row level security;


-- ==================== 045_portal_chat.sql ====================
-- Migration 045 — Client Portal AI chat (portal_conversations + portal_messages)  (UP)
-- Stores the client-facing reflection chat. Both tables are reached only via the
-- service-role admin client and every query is app-scoped to the authenticated
-- portal client (RLS enabled, no policy — consistent with the schema). The AI
-- context is built from the client's OWN goals + transcripts; coach-private
-- fields (key_info, coach notes) are never included.
-- Reversible via 045_portal_chat_down.sql.

create table if not exists portal_conversations (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null default '00000000-0000-4000-8000-000000000001'
                references organizations(id),
  client_id   uuid not null references clients(id) on delete cascade,
  title       text not null default 'New conversation',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists portal_conversations_client_idx
  on portal_conversations (client_id, updated_at desc);
create index if not exists portal_conversations_org_id_idx
  on portal_conversations (org_id);

create table if not exists portal_messages (
  id               uuid primary key default gen_random_uuid(),
  org_id           uuid not null default '00000000-0000-4000-8000-000000000001'
                     references organizations(id),
  conversation_id  uuid not null references portal_conversations(id) on delete cascade,
  role             text not null,   -- 'user' | 'assistant'
  content          text not null,
  created_at       timestamptz not null default now()
);
create index if not exists portal_messages_conversation_idx
  on portal_messages (conversation_id, created_at);
create index if not exists portal_messages_org_id_idx
  on portal_messages (org_id);

alter table portal_conversations enable row level security;
alter table portal_messages enable row level security;


-- ==================== 046_signature_owner.sql ====================
-- 046: Attach the seeded global email signature to Jeff's coach row.
--
-- Multi-coach change: signature resolution no longer falls back to the global
-- (coach_id IS NULL) row for coaches with an identity — that row carries Jeff's
-- personal signature, which must never append under another coach's email.
-- Coaches without a saved signature now get a generic TLW signature built from
-- their own name/email, and can build their own in Account → Email signature.
--
-- This migration preserves Jeff's existing signature exactly by converting the
-- seeded global row into HIS coach-specific row (only if he doesn't already
-- have one). Target: the coach row with email jeff@jeffkholmes.com, else the
-- EARLIEST-created coach row (Jeff is the founding coach in this database) —
-- so a different sign-in address can't silently strand the signature.
-- Idempotent; safe to re-run. No schema change.

with jeff as (
  select id from coaches
  order by (email = 'jeff@jeffkholmes.com') desc, created_at asc
  limit 1
)
update email_signatures
set coach_id = (select id from jeff)
where coach_id is null
  and exists (select 1 from jeff)
  and not exists (
    select 1 from email_signatures es2
    where es2.coach_id = (select id from jeff)
  );


-- ==================== 047_coach_calendar_and_transcript_source.sql ====================
-- 047: Per-coach calendar selection + transcript source (beta coach settings).
--
-- calendar_id — which Google calendar the app reads/writes for this coach
--   (transcript matching, session booking, conflict checks, reminders, external
--   booking capture). NULL = the primary calendar (the pre-047 behavior, so
--   existing coaches are unchanged). Set in Account → Calendar.
--
-- transcript_source — where this coach's transcripts come from:
--   'manual' (default; per-client file upload) | 'plaud' | 'zoom'.
--   Plaud/Zoom automated intake are post-beta; for now the setting records the
--   coach's choice and drives the Account → Transcript source panel. NULL reads
--   as 'manual'.
--
-- Additive only; no backfill needed.

alter table coaches add column if not exists calendar_id text;
alter table coaches add column if not exists transcript_source text;


-- ==================== 048_supervisor_bootstrap_and_signature_unique.sql ====================
-- 048: Supervisor bootstrap + one-signature-per-coach index.
--
-- (1) Supervisor bootstrap. /api/coaches (list/add/edit/delete coaches) is now
--     gated by requireSupervisor — but coaches rows default to role='coach', so
--     without at least one supervisor NOBODY can reach coach management (the
--     promote action is itself gated). Promote the founding coach: the row with
--     email jeff@jeffkholmes.com, else the earliest-created coach. No-op if a
--     supervisor already exists. Idempotent.
--
-- (2) Unique signature per coach. The Account → Email signature editor upserts
--     the coach's email_signatures row; without a uniqueness guarantee a save
--     race can duplicate rows. NULLs stay allowed (the historical global row).
--     Duplicate coach rows (if any ever appeared) are collapsed to the newest
--     before the index is created.

-- (1) Bootstrap a supervisor if none exists.
update coaches
set role = 'supervisor'
where id = (
  select id from coaches
  order by (email = 'jeff@jeffkholmes.com') desc, created_at asc
  limit 1
)
and not exists (select 1 from coaches where role = 'supervisor');

-- (2) Collapse any duplicate per-coach signature rows (keep the newest) …
delete from email_signatures es
where es.coach_id is not null
  and exists (
    select 1 from email_signatures newer
    where newer.coach_id = es.coach_id
      and (newer.updated_at > es.updated_at
           or (newer.updated_at = es.updated_at and newer.id > es.id))
  );

-- … then guarantee one row per coach (NULL coach_id rows are not constrained).
create unique index if not exists email_signatures_coach_uidx
  on email_signatures (coach_id);


-- ==================== 049_coaching_hours_entries.sql ====================
-- Migration 049 — Coaching hours entries (imported / historical hours)  (UP)
-- Makes the app the canonical record of the coach's lifetime coaching hours:
-- rows imported from a CSV, logged by hand, or entered as a single aggregate
-- "prior hours" block covering pre-platform coaching. These merge with the
-- note-derived session log in /api/coaching-hours and feed the ICF PDF export.
-- client_label is free text — historical clients need not exist in the roster.
-- Reversible via 049_coaching_hours_entries_down.sql.

create table if not exists coaching_hours_entries (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null default '00000000-0000-4000-8000-000000000001'
                      references organizations(id),
  coach_id          uuid not null references coaches(id) on delete cascade,
  session_date      date not null,
  duration_minutes  integer not null check (duration_minutes > 0),
  client_label      text not null,                     -- free-text client / block label
  title             text,                              -- optional description
  kind              text not null default 'session',   -- 'session' | 'aggregate' (a block of prior hours)
  paid              boolean not null default true,     -- ICF logs split paid vs pro-bono
  source            text not null default 'manual',    -- 'manual' | 'csv'
  created_at        timestamptz not null default now()
);

create index if not exists coaching_hours_entries_coach_idx
  on coaching_hours_entries (coach_id, session_date desc);
create index if not exists coaching_hours_entries_org_id_idx
  on coaching_hours_entries (org_id);

alter table coaching_hours_entries enable row level security;


-- ==================== 050_note_sent_to_client.sql ====================
-- Migration 050 — record which notes were sent to the client  (UP)
--
-- Until now `POST /api/clients/[id]/send-note` sent the client-facing email and
-- returned WITHOUT logging anything: no `communications` row, no stamp on the
-- note. So there was no record anywhere of which notes a client had been sent,
-- or of what those emails said.
--
-- That record is the gate the Client Portal reads: the portal shows ONLY notes
-- the coach actually sent via "Send to client" — never raw coach notes. It also
-- closes a coach-side gap, since sent notes were missing from the workspace
-- "Recent Communication" card while every other send path logged normally.
--
-- The SENT VERSION (the AI-drafted client-facing narrative plus its Insights and
-- Actions sections) lives in `communications.body_html` under the new
-- `type = 'session_note'` — `communications.type` is unconstrained text, so no
-- DDL is needed for the type itself. These two columns are the note-side link.
--
-- Additive and nullable: existing notes read as never-sent, which is correct —
-- the data was never recorded, so there is nothing to backfill. The portal's
-- notes history therefore begins the day this ships.
--
-- Reversible via 050_note_sent_to_client_down.sql.

alter table notes
  add column if not exists sent_to_client_at timestamptz,
  -- The communications row holding the exact email the client received. ON DELETE
  -- SET NULL so pruning the comms log can never delete a coach's note.
  add column if not exists client_communication_id uuid
    references communications(id) on delete set null;

-- The portal lists a client's sent notes newest-first; partial (sent only) since
-- unsent notes are the majority and are never queried through this path.
create index if not exists notes_sent_to_client_idx
  on notes (client_id, sent_to_client_at desc)
  where sent_to_client_at is not null;

-- The portal reads sent notes out of the communications log by type.
create index if not exists communications_client_type_idx
  on communications (client_id, type, sent_at desc);


-- ==================== 051_coach_booking_url.sql ====================
-- Migration 051 — per-coach client-facing booking link  (UP)
--
-- The Client Portal's "Schedule your next session" button. Clients book through
-- the coach's own scheduler (HubSpot Meetings, Calendly, etc.), which already
-- writes the booking to the coach's Google Calendar — so the existing
-- calendar-watch capture (migration 025) picks it up and surfaces it as the
-- client's Next Appointment with no per-provider integration.
--
-- Until now this link existed in exactly one place: hand-written into the "Book
-- a session →" line of the seeded email signature. This promotes it to a real
-- per-coach column so the portal and the signature can read one value.
--
-- Additive and nullable: NULL simply means the portal shows no booking button.
-- Reversible via 051_coach_booking_url_down.sql.

alter table coaches
  add column if not exists booking_url text;

-- Seed the founding coach's existing HubSpot link (the one already living in the
-- seeded signature) so the portal button works on day one. Idempotent, and
-- scoped so it can never overwrite a coach who has already set their own.
update coaches
   set booking_url = 'https://meetings-na2.hubspot.com/dr-jeff'
 where booking_url is null
   and email in ('jeff@jeffkholmes.com', 'jeff@theleadershipwell.com');


-- ==================== 052_portal_search.sql ====================
-- Migration 052 — Client Portal full-text search  (UP)
--
-- The portal's search was `ilike '%term%'` over `transcripts.raw_md`. A leading
-- wildcard can't use an index, so every search sequentially scanned all of the
-- client's transcripts and pulled each full `raw_md` into the app. It also
-- couldn't reach session notes at all, matched substrings rather than words
-- (no stemming, no ranking), and returned only the FIRST hit per session.
--
-- This replaces it with real Postgres full-text search over both sources the
-- client is allowed to see:
--   * their own session transcripts
--   * the session notes the coach SENT them (communications, migration 050)
-- Coach-private notes are never indexed — the `notes` table is not touched here.
--
-- Both vectors are GENERATED ... STORED, so they stay correct with no write-path
-- change and no backfill: Postgres computes them for existing rows as part of
-- this migration and for every future insert/update.
--
-- Reversible via 052_portal_search_down.sql.

-- Lets a GIN index carry `client_id` alongside the tsvector, so a search scans
-- only THIS client's rows instead of matching every tenant's rows for a common
-- word and filtering afterwards. Verified with EXPLAIN: client_id lands in the
-- Index Cond rather than a post-scan Filter.
create extension if not exists btree_gin;

-- ---------------------------------------------------------------------------
-- Transcripts: title carries extra weight ('A') over the body ('B'), so a hit in
-- a session's title ranks above a passing mention inside another session.
-- ---------------------------------------------------------------------------
alter table transcripts
  add column if not exists search_vector tsvector
    generated always as (
      setweight(to_tsvector('english', coalesce(title, '')), 'A') ||
      setweight(to_tsvector('english', coalesce(raw_md, '')), 'B')
    ) stored;

create index if not exists transcripts_search_idx
  on transcripts using gin (client_id, search_vector);

-- ---------------------------------------------------------------------------
-- Communications: `body_html` is an email document, so tags are stripped before
-- indexing or every row would match on "table", "td", "style", etc. The index is
-- partial — only sent session notes are ever searched from the portal.
-- ---------------------------------------------------------------------------
alter table communications
  add column if not exists search_vector tsvector
    generated always as (
      setweight(to_tsvector('english', coalesce(subject, '')), 'A') ||
      setweight(
        to_tsvector('english', regexp_replace(coalesce(body_html, ''), '<[^>]*>', ' ', 'g')),
        'B'
      )
    ) stored;

create index if not exists communications_session_note_search_idx
  on communications using gin (client_id, search_vector)
  where type = 'session_note';

-- ---------------------------------------------------------------------------
-- One ranked query across both sources.
--
-- Highlights are delimited with SENTINEL TEXT, not <mark> tags: the caller
-- splits on them and renders the highlight itself, so transcript content can
-- never inject markup into a client-facing page.
--
-- `websearch_to_tsquery` is used deliberately — it accepts anything a person
-- types (quotes, OR, bare punctuation) without raising, unlike `to_tsquery`.
--
-- Scoped by p_client_id. The caller passes the authenticated portal client id;
-- there is no path here that reads another client's rows.
-- ---------------------------------------------------------------------------
create or replace function portal_search(
  p_client_id uuid,
  p_query     text,
  p_limit     int default 20
)
returns table (
  kind        text,
  id          uuid,
  title       text,
  occurred_on date,
  snippet     text,
  rank        real
)
language sql
stable
as $$
  with q as (
    select websearch_to_tsquery('english', p_query) as tsq
  )
  select
    'session'::text                                   as kind,
    t.id                                              as id,
    coalesce(nullif(btrim(t.title), ''), 'Session')   as title,
    t.session_date                                    as occurred_on,
    ts_headline(
      'english',
      coalesce(t.raw_md, ''),
      q.tsq,
      'StartSel="[[hl]]", StopSel="[[/hl]]", MaxWords=45, MinWords=20, MaxFragments=2, FragmentDelimiter=" … "'
    )                                                 as snippet,
    ts_rank(t.search_vector, q.tsq)                   as rank
  from transcripts t, q
  where t.client_id = p_client_id
    and t.search_vector @@ q.tsq

  union all

  select
    'note'::text,
    c.id,
    coalesce(nullif(btrim(c.subject), ''), 'Session notes'),
    c.sent_at::date,
    ts_headline(
      'english',
      regexp_replace(coalesce(c.body_html, ''), '<[^>]*>', ' ', 'g'),
      q.tsq,
      'StartSel="[[hl]]", StopSel="[[/hl]]", MaxWords=45, MinWords=20, MaxFragments=2, FragmentDelimiter=" … "'
    ),
    ts_rank(c.search_vector, q.tsq)
  from communications c, q
  where c.client_id = p_client_id
    and c.type = 'session_note'
    and c.direction = 'outbound'
    and c.status = 'sent'
    and c.search_vector @@ q.tsq

  order by rank desc, occurred_on desc nulls last
  limit greatest(1, least(coalesce(p_limit, 20), 50));
$$;


-- ==================== 053_portal_access_log.sql ====================
-- Migration 053 — Client Portal access log, onboarding flag, chat retrieval  (UP)
--
-- Three additive pieces, all serving the portal:
--
-- 1. `portal_access_log` — one row per notable portal action. Serves two jobs at
--    once: an audit trail for the surface that holds a client's full session
--    history, and the counter behind per-client rate limiting. Rate limiting has
--    to be durable rather than in-process because the app runs serverless, where
--    an in-memory counter resets on every cold start and isn't shared between
--    concurrent instances.
--
-- 2. `clients.portal_onboarded` — moves the first-visit tour flag off
--    localStorage (per-browser, so it re-fires on every new device and can never
--    be replayed deliberately) and onto the client record.
--
-- 3. `portal_chat_context` — the retrieval function behind the AI chat. The chat
--    previously stuffed the newest ~40k characters of transcripts into every
--    request and stopped, so a client more than a handful of sessions in
--    silently lost their oldest material — exactly what they come to the chat to
--    remember. This returns the passages relevant to the question asked,
--    drawn from the client's whole history, using the search vectors added in
--    migration 052.
--
-- Reversible via 053_portal_access_log_down.sql.

create table if not exists portal_access_log (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null default '00000000-0000-4000-8000-000000000001'
                references organizations(id),
  client_id   uuid not null references clients(id) on delete cascade,
  -- 'login_request' | 'login_verify' | 'login_password' | 'password_set'
  -- | 'chat' | 'contact' | 'upload' | 'note_view' | 'session_view' | 'pdf_view'
  action      text not null,
  -- Optional detail (a row id, a failure reason). Never the content itself.
  detail      text,
  ok          boolean not null default true,
  created_at  timestamptz not null default now()
);

-- The rate-limit query: "how many <action> rows for this client since <time>".
create index if not exists portal_access_log_rate_idx
  on portal_access_log (client_id, action, created_at desc);
create index if not exists portal_access_log_org_id_idx
  on portal_access_log (org_id);

alter table portal_access_log enable row level security;

-- First-visit tour, per client rather than per browser. NULL/false = not yet
-- taken; the portal also offers a "take the tour again" affordance.
alter table clients
  add column if not exists portal_onboarded boolean not null default false;

-- ---------------------------------------------------------------------------
-- Retrieval for the AI chat.
--
-- Same two sources and the same hard client scoping as `portal_search`, but
-- tuned for feeding a model rather than rendering a result list: bigger
-- fragments, more of them, and no highlight sentinels. Ordered by relevance so
-- the caller can take the top N under a character budget.
-- ---------------------------------------------------------------------------
create or replace function portal_chat_context(
  p_client_id uuid,
  p_query     text,
  p_limit     int default 8
)
returns table (
  kind        text,
  id          uuid,
  title       text,
  occurred_on date,
  excerpt     text,
  rank        real
)
language sql
stable
as $$
  with q as (
    select websearch_to_tsquery('english', p_query) as tsq
  )
  select
    'session'::text                                   as kind,
    t.id                                              as id,
    coalesce(nullif(btrim(t.title), ''), 'Session')   as title,
    t.session_date                                    as occurred_on,
    ts_headline(
      'english',
      coalesce(t.raw_md, ''),
      q.tsq,
      'StartSel="", StopSel="", MaxWords=160, MinWords=80, MaxFragments=4, FragmentDelimiter=" … "'
    )                                                 as excerpt,
    ts_rank(t.search_vector, q.tsq)                   as rank
  from transcripts t, q
  where t.client_id = p_client_id
    and t.search_vector @@ q.tsq

  union all

  select
    'note'::text,
    c.id,
    coalesce(nullif(btrim(c.subject), ''), 'Session notes'),
    c.sent_at::date,
    ts_headline(
      'english',
      regexp_replace(coalesce(c.body_html, ''), '<[^>]*>', ' ', 'g'),
      q.tsq,
      'StartSel="", StopSel="", MaxWords=160, MinWords=80, MaxFragments=4, FragmentDelimiter=" … "'
    ),
    ts_rank(c.search_vector, q.tsq)
  from communications c, q
  where c.client_id = p_client_id
    and c.type = 'session_note'
    and c.direction = 'outbound'
    and c.status = 'sent'
    and c.search_vector @@ q.tsq

  order by rank desc, occurred_on desc nulls last
  limit greatest(1, least(coalesce(p_limit, 8), 20));
$$;


-- ==================== 054_client_credentials.sql ====================
-- Migration 054 — Client Portal username + password  (UP)
--
-- The portal shipped with magic-link sign-in only. This adds an optional
-- username + password a client can set for themselves; the magic link stays as
-- the recovery path (and as the way a coach gets a client back in).
--
-- The hash lives in its OWN table rather than on `clients` on purpose: portal
-- and coach code select from `clients` constantly, sometimes with `select *`,
-- and a password hash must never ride along in one of those payloads by
-- accident. A separate table makes leaking it require a deliberate join.
--
-- What the coach can see is `username`, whether a password is set, and
-- `last_login_at` — never the password, which is a one-way hash. The coach's
-- affordances are "resend the sign-in link" (the existing portal-invite route)
-- and, implicitly, "the client can reset it themselves".
--
-- Reversible via 054_client_credentials_down.sql.

create table if not exists client_credentials (
  client_id       uuid primary key references clients(id) on delete cascade,
  org_id          uuid not null default '00000000-0000-4000-8000-000000000001'
                    references organizations(id),
  -- Lowercased at write time; unique across the whole install so sign-in needs
  -- only the username, not a tenant hint.
  username        text not null unique,
  -- scrypt: "scrypt$N$r$p$<salt-b64>$<hash-b64>". Never reversible, never shown.
  password_hash   text not null,
  -- Throttling state for the password form. The magic-link limiter doesn't
  -- cover this path — a password field invites guessing in a way a link doesn't.
  failed_attempts int not null default 0,
  locked_until    timestamptz,
  last_login_at   timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- Sign-in looks the row up by username; the PK covers the client_id direction.
create index if not exists client_credentials_username_idx
  on client_credentials (username);
create index if not exists client_credentials_org_id_idx
  on client_credentials (org_id);

alter table client_credentials enable row level security;


-- ==================== 055_client_frameworks.sql ====================
-- Migration 055 — frameworks surfaced to a client  (UP)
--
-- The portal's Frameworks card previously derived its list from the client's
-- `type='framework'` nudges, so a framework only appeared if a nudge about it
-- was actually drafted and kept. The nudge pipeline already detects when a
-- session NAMES a framework — but that detection is then mostly discarded by
-- the 2-per-window cap, which is about how much mail a client should get, not
-- about what they've discussed.
--
-- This records every detected framework relationship at scoring time,
-- independent of whether a nudge survives. `source` distinguishes the two:
--   'mentioned' — the coach named it in a scored session
--   'nudged'    — a framework nudge was sent about it
--   'coach'     — assigned by hand (also used to correct a false positive)
--
-- `dismissed_at` is the coach's override: a mention the model got wrong is
-- hidden from the client without deleting the record of the detection.
--
-- Reversible via 055_client_frameworks_down.sql.

create table if not exists client_frameworks (
  id             uuid primary key default gen_random_uuid(),
  org_id         uuid not null default '00000000-0000-4000-8000-000000000001'
                   references organizations(id),
  client_id      uuid not null references clients(id) on delete cascade,
  coach_id       uuid not null references coaches(id) on delete cascade,
  -- Matches garden_notes.id (the leaf slug). No FK: the garden index is rebuilt
  -- wholesale by vault sync, and a leaf briefly missing mid-sync must not
  -- cascade-delete a client's history. Reads re-check the leaf and its
  -- nudge_eligible gate anyway.
  framework_slug text not null,
  source         text not null default 'mentioned',
  -- The transcript the mention came from, when it came from one.
  transcript_id  uuid references transcripts(id) on delete set null,
  dismissed_at   timestamptz,
  first_seen_at  timestamptz not null default now(),
  last_seen_at   timestamptz not null default now()
);

-- One row per client per framework; repeat mentions bump last_seen_at.
create unique index if not exists client_frameworks_unique_idx
  on client_frameworks (client_id, framework_slug);
create index if not exists client_frameworks_client_idx
  on client_frameworks (client_id, dismissed_at);
create index if not exists client_frameworks_org_id_idx
  on client_frameworks (org_id);

alter table client_frameworks enable row level security;


-- ==================== 056_invoice_reminder_ladder.sql ====================
-- 056_invoice_reminder_ladder.sql
-- Invoice reminder ladder (invoices are due on receipt).
--
-- Replaces the single one-shot 14-day reminder with a cadence, anchored to the
-- send date and paced ~14 days apart (each rung is scheduled when the previous
-- one actually sends, so late/backfilled invoices never get burst-emailed):
--
--   nudge_14d   ~day 14  gentle reminder (the legacy reminder, unchanged tone)
--   overdue_1   ~day 28  flips the invoice sent → overdue + firmer notice
--   overdue_2   ~day 42  final automated client reminder
--   coach_alert ~day 56  no client email — notifies the COACH ("needs
--                        attention") and stamps invoices.reminders_exhausted_at
--
-- Each rung fires at most once per invoice, enforced by a real UNIQUE index
-- (the old claim logic only approximated this). Cancellation on paid/void is
-- unchanged and kills the whole remaining ladder.

-- 1. Rung identity. Existing rows are all the legacy single 14-day reminder,
--    which is exactly the ladder's first rung — the default backfills them.
ALTER TABLE invoice_reminders
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'nudge_14d';

-- 2. Collapse any duplicate (invoice_id, kind) rows so the unique index can
--    build (in practice there is at most one row per invoice today).
DELETE FROM invoice_reminders a
  USING invoice_reminders b
  WHERE a.invoice_id = b.invoice_id
    AND a.kind = b.kind
    AND a.id > b.id;

-- 3. One firing per rung per invoice — the hard double-send guard.
CREATE UNIQUE INDEX IF NOT EXISTS invoice_reminders_invoice_kind_uniq
  ON invoice_reminders(invoice_id, kind);

-- 4. Needs-attention stamp, set when the ladder exhausts (coach_alert rung):
--    the signal that automated reminders are done and a personal follow-up is
--    owed. Cleared implicitly by being irrelevant once the invoice is paid.
ALTER TABLE invoices
  ADD COLUMN IF NOT EXISTS reminders_exhausted_at timestamptz;

-- 5. Backfill: outstanding invoices whose legacy 14-day reminder already fired
--    rejoin the cadence at the next rung. Scheduled at least 1 day out so
--    nothing blasts the moment the next cron run happens.
INSERT INTO invoice_reminders (invoice_id, kind, send_at, status, channel)
SELECT r.invoice_id,
       'overdue_1',
       GREATEST(COALESCE(r.sent_at, now()) + interval '14 days', now() + interval '1 day'),
       'scheduled',
       'email'
FROM invoice_reminders r
JOIN invoices i ON i.id = r.invoice_id
WHERE r.kind = 'nudge_14d'
  AND r.status = 'sent'
  AND i.status IN ('sent', 'overdue')
ON CONFLICT (invoice_id, kind) DO NOTHING;


-- ==================== 057_coach_plans_admin.sql ====================
-- Migration 057 — Coach plans, coach billing (Stripe subscription), admin audit log  (UP)
--
-- The Admin Command Center (Business Center → Command Center) needs three things:
--
-- 1. A per-coach PLAN — beta | free | paying — so the supervisor can see at a
--    glance who is beta testing, who rides free, and who pays. `plan` is
--    hand-set from the command center; `plan_note` is a free-text annotation
--    ("comped through Q4", "founding tester").
--
-- 2. Coach BILLING state — a Stripe subscription per coach, collected via
--    Stripe hosted Checkout (subscription mode; card entry never touches a TLW
--    page). `stripe_customer_id` / `stripe_subscription_id` tie the coach row
--    to Stripe; `subscription_status` mirrors Stripe's status (active,
--    trialing, past_due, canceled, …) via webhook. An active/trialing
--    subscription auto-promotes `plan` to 'paying'; a canceled one drops it to
--    'free' — but `plan` stays hand-editable for comped/beta arrangements.
--
-- 3. `admin_audit_log` — one append-only row per supervisor admin action
--    (plan change, on-behalf portal invite resend, portal unlock, billing link
--    sent), so "who did what to whose account" is always answerable.
--
-- All additive. Reversible via 057_coach_plans_admin_down.sql.

-- 1. Plan label. Unconstrained text (consistent with the rest of the schema);
--    the app writes only beta | free | paying. Existing coaches read as 'beta'.
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS plan text NOT NULL DEFAULT 'beta';
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS plan_note text;

-- 2. Coach billing (Stripe subscription).
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS stripe_customer_id text;
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS stripe_subscription_id text;
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS subscription_status text;

-- The webhook resolves a subscription event back to a coach by these ids.
CREATE INDEX IF NOT EXISTS coaches_stripe_customer_idx
  ON coaches (stripe_customer_id) WHERE stripe_customer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS coaches_stripe_subscription_idx
  ON coaches (stripe_subscription_id) WHERE stripe_subscription_id IS NOT NULL;

-- 3. Admin audit log (append-only; never updated or deleted by the app).
CREATE TABLE IF NOT EXISTS admin_audit_log (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                     REFERENCES organizations(id),
  -- Who did it. SET NULL so removing a coach never destroys the audit trail.
  actor_coach_id   uuid REFERENCES coaches(id) ON DELETE SET NULL,
  -- 'plan_change' | 'portal_invite_resend' | 'portal_unlock'
  -- | 'billing_checkout_link' | 'coach_added' | 'coach_removed' | …
  action           text NOT NULL,
  target_coach_id  uuid REFERENCES coaches(id) ON DELETE SET NULL,
  target_client_id uuid REFERENCES clients(id) ON DELETE SET NULL,
  -- Small structured context (old/new plan, sent-to email). Never secrets.
  detail           jsonb,
  created_at       timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS admin_audit_log_created_idx
  ON admin_audit_log (created_at DESC);
CREATE INDEX IF NOT EXISTS admin_audit_log_org_id_idx
  ON admin_audit_log (org_id);

ALTER TABLE admin_audit_log ENABLE ROW LEVEL SECURITY;


-- ==================== 058_session_plans.sql ====================
-- Migration 058 — saved session plans  (UP)
--
-- "Plan next session" was fully ephemeral: the generated brief and the coach's
-- notepad lived only in the open window (notes in localStorage). Beta feedback:
-- the coach generates a plan days ahead, writes their OWN plan in the notepad,
-- and wants to come back to exactly that document on the day of the session —
-- from any device. This table makes a plan a savable document.
--
--   plan   — the generated brief (PlanResult JSON: summary, questions, and the
--            deterministic context lists) frozen at save time
--   notes  — the coach's own plan from the window's notepad (autosaved on edit)
--   title  — display label, defaulted server-side to "Session plan · <date>"
--
-- Surfaced in the client workspace "Session plans" card; opening a row loads it
-- back into the floating plan window / pop-out.
--
-- Reversible via 058_session_plans_down.sql.

create table if not exists session_plans (
  id         uuid primary key default gen_random_uuid(),
  org_id     uuid not null default '00000000-0000-4000-8000-000000000001'
               references organizations(id),
  coach_id   uuid not null references coaches(id) on delete cascade,
  client_id  uuid not null references clients(id) on delete cascade,
  title      text not null default '',
  plan       jsonb not null,
  notes      text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists session_plans_client_idx
  on session_plans (client_id, created_at desc);
create index if not exists session_plans_org_id_idx
  on session_plans (org_id);

alter table session_plans enable row level security;


-- ==================== 059_assessment_debrief_foundation.sql ====================
-- Migration 059 — Assessment debrief foundation  (UP)
--
-- Phase 1 of the document-grounded assessment debrief capability (first
-- instrument: the Zenger Folkman Extraordinary Leader 360). This is a FEATURE
-- FLAG on the existing Client Portal, not a second portal: same clients table,
-- same login, same chat. Nothing here changes behavior for any existing client —
-- every new column is nullable or defaulted, and the flag (portal_features)
-- defaults to {} so the 360 surfaces stay hidden until switched on per client.
--
-- Instrument-agnostic by design: no table, column, or value is named after ZF.
-- ZF-specific logic lives in ONE place — a versioned row in prompt_briefs.
--
-- What this adds:
--   1. companies            — client companies (vision/values feed chat context)
--   2. cohorts              — a contracted program at a company (seats, access window)
--   3. client_documents     — uploaded assessments/reviews + structured extraction
--   4. prompt_briefs        — versioned interpretation briefs, editable without a deploy
--   5. support_tickets (+ messages) — "Contact support" for clients with no coach
--   6. portal_events        — outcomes instrumentation (captured from day one)
--   7. clients: client_type gains 'portal'; cohort_id, company_id,
--      portal_features, portal_access_expires_at
--   8. portal_messages.metadata — stamps which brief version produced a reply
--
-- All new tables: org_id (042 pattern) + RLS enabled, no policies (service-role
-- only, consistent with the schema). Reversible via
-- 059_assessment_debrief_foundation_down.sql.

-- ---------------------------------------------------------------------------
-- 1. companies — a client company. vision/values are plain text the chat
--    includes ONLY for clients whose company_id points here (never a placeholder
--    when absent).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS companies (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id      uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                REFERENCES organizations(id),
  name        text NOT NULL,
  vision      text,
  "values"    text,
  notes       text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS companies_org_id_idx ON companies (org_id);
ALTER TABLE companies ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- 2. cohorts — one contracted program (e.g. "Q4 2026 leadership cohort") at a
--    company. Billing is on seats_purchased; seats activated is COUNTED from
--    clients.cohort_id, never stored. debrief_coach_name is text on purpose:
--    the debrief coaches have no app access in v1 (no coaches row, no role).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cohorts (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id              uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                        REFERENCES organizations(id),
  company_id          uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  name                text NOT NULL,
  seats_purchased     integer NOT NULL DEFAULT 0 CHECK (seats_purchased >= 0),
  access_starts_at    timestamptz,
  access_expires_at   timestamptz,
  debrief_coach_name  text,
  -- 'active' | 'closed'
  status              text NOT NULL DEFAULT 'active',
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS cohorts_company_idx ON cohorts (company_id);
CREATE INDEX IF NOT EXISTS cohorts_org_id_idx ON cohorts (org_id);
ALTER TABLE cohorts ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- 3. client_documents — an uploaded document plus its extraction. The PDF itself
--    lives in the private Storage bucket `client-documents` at storage_path
--    (`${client_id}/${id}.pdf`); the bucket is created in code on first upload.
--
--    kind:              'assessment_360' | 'personnel_review' | 'company_doc'
--    uploader_role:     'coach' | 'client'
--    extraction_status: 'pending' | 'complete' | 'failed' | 'unsupported'
--    visible_to_coach:  enforced at the QUERY layer on every coach-side read —
--                       a personnel_review is always false and never surfaces
--                       to any coach.
--    assessment_date:   parsed from the report cover; the ORDERING key for
--                       longitudinal comparison (never created_at — an older
--                       report may be uploaded after a newer one).
--    supersedes_document_id: the prior assessment this one is compared against.
--    structured_data:   validated JSON, the sole source of truth for any number
--                       the AI states. Rater names are stripped before storage.
--    A document with extraction_status <> 'complete' is never client-visible and
--    never enters chat context; it IS still downloadable by its owner.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS client_documents (
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id                   uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                             REFERENCES organizations(id),
  client_id                uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  kind                     text NOT NULL,
  title                    text,
  storage_path             text NOT NULL,
  size_bytes               integer,
  extracted_text           text,
  structured_data          jsonb,
  extraction_status        text NOT NULL DEFAULT 'pending',
  extraction_error         text,
  -- Who uploaded it: a coaches row when uploader_role='coach', else NULL.
  uploaded_by              uuid REFERENCES coaches(id) ON DELETE SET NULL,
  uploader_role            text NOT NULL,
  visible_to_coach         boolean NOT NULL DEFAULT false,
  assessment_date          date,
  instrument               text,
  format_version           text,
  supersedes_document_id   uuid REFERENCES client_documents(id) ON DELETE SET NULL,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS client_documents_client_kind_date_idx
  ON client_documents (client_id, kind, assessment_date DESC);
CREATE INDEX IF NOT EXISTS client_documents_status_idx
  ON client_documents (extraction_status) WHERE extraction_status <> 'complete';
CREATE INDEX IF NOT EXISTS client_documents_org_id_idx ON client_documents (org_id);
ALTER TABLE client_documents ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- 4. prompt_briefs — versioned interpretation briefs, one slug per document
--    kind/instrument. Exactly one row per slug is_active at a time; the chat
--    loads the active row and stamps its version into portal_messages.metadata.
--    Editable from the command center — a brief change never needs a deploy.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS prompt_briefs (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id      uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                REFERENCES organizations(id),
  slug        text NOT NULL,
  version     integer NOT NULL DEFAULT 1,
  title       text NOT NULL,
  body        text NOT NULL,
  is_active   boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (org_id, slug, version)
);
CREATE UNIQUE INDEX IF NOT EXISTS prompt_briefs_one_active_per_slug
  ON prompt_briefs (org_id, slug) WHERE is_active;
ALTER TABLE prompt_briefs ENABLE ROW LEVEL SECURITY;

-- Placeholder brief so the pipeline is testable end to end. Jeff replaces the
-- body from the command center (a new version row) — the guardrails below are
-- the non-negotiable floor that every version must keep.
INSERT INTO prompt_briefs (slug, version, title, body, is_active)
SELECT 'assessment_360', 1, 'Assessment 360 interpretation brief (placeholder v1)',
$brief$You are helping a leader make sense of their 360 feedback report. They have already had a group debrief with a human coach; you are a thinking partner for what comes next, not a first-contact interpreter.

Non-negotiables:
- A 360 measures PERCEPTION, not ability. Say what raters saw ("your peers saw this as a standout"), never what the person is ("you are strong at this").
- Lead from strengths. Low scores are context, never the agenda.
- Never rank competencies by score. Rank by band, then by score within band.
- Never invent a score, percentile, or comment. If it is not in the structured data, it does not exist.
- Never speculate about which individual said or scored what, in any framing.
- Never tell the participant what their goals should be. Surface where the data points, then ask what they make of it.
- Treat absent or collapsed sections (e.g. Engagement 0.00 from too few direct reports) as absent, not as scores.
- Raise context (new role, new manager, reorganisation, a hard year) as a live explanation before personal attribution.
- When discussing change between two reports, offer it gently for reflection; never assert improvement or decline as fact, and never attribute it to coaching.$brief$,
  true
WHERE NOT EXISTS (SELECT 1 FROM prompt_briefs WHERE slug = 'assessment_360');

-- ---------------------------------------------------------------------------
-- 5. support_tickets — "Contact support" for portal clients who have no coach
--    to email. A coaching client keeps the existing Contact-your-coach card.
--    status: 'open' | 'closed'.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS support_tickets (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                 REFERENCES organizations(id),
  client_id    uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  subject      text NOT NULL,
  body         text NOT NULL,
  status       text NOT NULL DEFAULT 'open',
  assigned_to  uuid REFERENCES coaches(id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  closed_at    timestamptz
);
CREATE INDEX IF NOT EXISTS support_tickets_status_idx
  ON support_tickets (status, created_at DESC);
CREATE INDEX IF NOT EXISTS support_tickets_client_idx ON support_tickets (client_id);
CREATE INDEX IF NOT EXISTS support_tickets_org_id_idx ON support_tickets (org_id);
ALTER TABLE support_tickets ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS support_ticket_messages (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                 REFERENCES organizations(id),
  ticket_id    uuid NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,
  -- 'client' | 'staff'
  author_role  text NOT NULL,
  author_id    uuid,
  body         text NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS support_ticket_messages_ticket_idx
  ON support_ticket_messages (ticket_id, created_at);
CREATE INDEX IF NOT EXISTS support_ticket_messages_org_id_idx
  ON support_ticket_messages (org_id);
ALTER TABLE support_ticket_messages ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- 6. portal_events — outcomes instrumentation. Separate from portal_access_log
--    on purpose: the access log is an audit/rate-limit counter that may be
--    pruned; this is the durable outcomes record (first login, report viewed,
--    chat started, goal created, metric defined, comparison viewed, talk-to-a-
--    coach clicked, self-rated progress at 30/90/180/365 days). Append-only.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS portal_events (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id      uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                REFERENCES organizations(id),
  client_id   uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  event_type  text NOT NULL,
  metadata    jsonb,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS portal_events_client_idx
  ON portal_events (client_id, created_at DESC);
CREATE INDEX IF NOT EXISTS portal_events_type_idx
  ON portal_events (event_type, created_at DESC);
CREATE INDEX IF NOT EXISTS portal_events_org_id_idx ON portal_events (org_id);
ALTER TABLE portal_events ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- 7. clients — the flag and the links.
--    client_type already exists (031: 'client' | 'coach'). It gains 'portal' =
--    a standalone assessment participant with no coaching relationship. The
--    existing 'client' value IS the coaching client; nothing is renamed.
--    portal_features is INDEPENDENT of client_type: a 'client' can have
--    {"assessments": true}; a 'portal' client can have it false until their
--    report lands. Default {} = today's portal, byte-identical.
-- ---------------------------------------------------------------------------
ALTER TABLE clients DROP CONSTRAINT IF EXISTS clients_client_type_check;
ALTER TABLE clients
  ADD CONSTRAINT clients_client_type_check
  CHECK (client_type IN ('client', 'coach', 'portal'));

ALTER TABLE clients ADD COLUMN IF NOT EXISTS company_id uuid
  REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE clients ADD COLUMN IF NOT EXISTS cohort_id uuid
  REFERENCES cohorts(id) ON DELETE SET NULL;
ALTER TABLE clients ADD COLUMN IF NOT EXISTS portal_features jsonb NOT NULL DEFAULT '{}'::jsonb;
-- Denormalised from the cohort at activation so a per-client extension is possible.
ALTER TABLE clients ADD COLUMN IF NOT EXISTS portal_access_expires_at timestamptz;

CREATE INDEX IF NOT EXISTS clients_cohort_idx ON clients (cohort_id) WHERE cohort_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS clients_company_idx ON clients (company_id) WHERE company_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 8. portal_messages.metadata — e.g. {"brief_slug":"assessment_360","brief_version":1}
--    so engagement can later be compared across brief revisions.
-- ---------------------------------------------------------------------------
ALTER TABLE portal_messages ADD COLUMN IF NOT EXISTS metadata jsonb;


-- ==================== 060_company_documents.sql ====================
-- Migration 060 — Company documents  (UP)
--
-- Enterprise sponsors give theLeadershipWell material (vision, values, a
-- leadership framework, a strategy deck) that should shape the chat experience
-- of THEIR participants. Until now the only company context was the two text
-- fields on `companies`. This table holds uploaded documents per company: the
-- file lives in the private `client-documents` bucket under
-- companies/<company_id>/<id>.<ext>; the extracted text is what the chat reads,
-- budgeted, for every client whose `clients.company_id` points at the company
-- and never for anyone else (the same strict lookup as vision/values).
--
-- Additive. RLS enabled, no policies (service-role only). Reversible via
-- 060_company_documents_down.sql.

CREATE TABLE IF NOT EXISTS company_documents (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id             uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                       REFERENCES organizations(id),
  company_id         uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  title              text NOT NULL,
  storage_path       text NOT NULL,
  size_bytes         integer,
  extracted_text     text,
  -- 'complete' | 'failed'
  extraction_status  text NOT NULL DEFAULT 'pending',
  extraction_error   text,
  -- Whether the text is fed to participants' chat (a sponsor may hand over a
  -- document for reference only).
  include_in_chat    boolean NOT NULL DEFAULT true,
  uploaded_by        uuid REFERENCES coaches(id) ON DELETE SET NULL,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS company_documents_company_idx ON company_documents (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS company_documents_org_id_idx ON company_documents (org_id);
ALTER TABLE company_documents ENABLE ROW LEVEL SECURITY;


-- ==================== 061_portal_profile_weekly_plans.sql ====================
-- Migration 061 — portal profile, weekly plans, chat modes
-- Procedure: docs/MIGRATION_PROCEDURE.md  (snapshot → staging → verify → prod)
--
-- Three additive pieces for the Client Portal (dry-run feedback round 3):
--
--  1. clients.preferred_name — "What should I call you": the name the portal
--     greets the client by and the assistant uses. NULL = first name of `name`.
--     `name` stays the legal/report name the 360 name-gate matches on.
--
--  2. portal_conversations.mode — 'general' (today's chat) or 'weekly_plan'
--     (the Plan-your-week conversation, which runs under the weekly_plan brief
--     instead of the general preamble). Default keeps every existing thread
--     'general'.
--
--  3. weekly_plans — the Top 5 for a week, saved from a weekly-plan chat after
--     the client confirms it. One plan per client per week (week_start = the
--     Monday). tasks = [{id, text, done, done_at}]. Checking a task off on the
--     portal home card updates the row in place.
--
--  4. A seeded `weekly_plan` prompt brief (Jeff's goal-setting master prompt),
--     editable from the command center's Brief tab like the 360 brief; a new
--     version row takes effect on the next message, no deploy.
--
-- All additive; reversible via 061_portal_profile_weekly_plans_down.sql.

ALTER TABLE clients ADD COLUMN IF NOT EXISTS preferred_name text;

ALTER TABLE portal_conversations
  ADD COLUMN IF NOT EXISTS mode text NOT NULL DEFAULT 'general';

CREATE TABLE IF NOT EXISTS weekly_plans (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                     REFERENCES organizations(id),
  client_id        uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  -- The Monday of the week the plan covers.
  week_start       date NOT NULL,
  title            text,
  -- [{ "id": "t1", "text": "…", "done": false, "done_at": null }, …]
  tasks            jsonb NOT NULL DEFAULT '[]'::jsonb,
  -- The chat that produced it (kept for "open the conversation"); null if deleted.
  conversation_id  uuid REFERENCES portal_conversations(id) ON DELETE SET NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS weekly_plans_client_week_idx
  ON weekly_plans (client_id, week_start);
CREATE INDEX IF NOT EXISTS weekly_plans_org_id_idx ON weekly_plans (org_id);
ALTER TABLE weekly_plans ENABLE ROW LEVEL SECURITY;

-- Seed the weekly-plan brief (v1). The body is the master prompt as supplied;
-- the leading PORTAL NOTES paragraph maps its terms onto what the portal holds.
INSERT INTO prompt_briefs (slug, version, title, body, is_active)
SELECT 'weekly_plan', 1, 'Plan your week — goal-setting coaching brief v1',
$brief$PORTAL NOTES (how this brief applies inside the portal): the person you are talking with is planning their week. Their "projects, OKRs, and goals" are the coaching goals, the 360 development areas, and the documents listed further down this prompt — draw on those; where a framework PDF is mentioned below and none is present, work from the framework as you know it and keep it light. The conversation should end with an agreed Top 5 for the week, stated plainly as a numbered list of five actions so it can be saved to their weekly plan. Ask before proposing; propose before finalising.

AI Master Prompt for Goal Setting

Your Persona:
I want you to function as a world class coach helping me to discover clarity from my thoughts and larger Objectives. I want you to use the OKR, and Traction frameworks as well as the Top 5 Things framework to help me build my goals (Refer to Uploaded PDFs for these frameworks). Also use the SMART goals framework to test my Objectives (which serve as the goals) as well as the Key Results (which are the sub goals).

Your Task:
Help me develop, solidify, and make actionable my big Objectives, my Key Results, and my weekly and daily Top 5 Things.

Specific Behavior:
When I say I am planning my week: First ask me what a successful week would look like. Use all you know about my business, goals, projects, and OKRs to suggest the most impactful goals for the week.
When I say I am planning my week, we will come up with the Top 5 actions to make the week a successful week.
When making suggestions for the Top 5 of the week, draw on my projects, OKRs, and goals.
When I say I am planning my day, ask me what success at the end of the day will look like.
When looking at actions for the day, generate a list of potential actions from projects, OKRs, and goals.
Remember and remind me of my key projects. List them in a table with the project title in the first column, the deliverables in the second column, and potential tasks for the week in the third column. Please suggest tasks for the week and list potential tasks already agreed to.
Remember my OKRs and present them in a table with the Objective in the first column, the KRs in the second column, and the measures in the third. In the fourth column, suggest current tasks to work on or list tasks I have decided I should work on.
Remember my goals and present them in a table with the Goal in the first column and the measures in the second column. In the third column, suggest current tasks to work on or list tasks I have decided I should work on.
Keep all names and information about myself or my clients personal to my account and never share them with the internet.
Help coach me with my goals driving toward SMART goals as well as following these guidelines:

Behavioral Guidelines
Mirror Only Emotionally Laden Responses — do not mirror factual statements.
One Goal at a Time — complete one conversational focus before moving on; if pivoting, explain why and recap what's unfinished.
One Question Only — each exchange ends with a single, clear, open-ended question. No bundles.
No Judgments or Praise — stay neutral; do not label progress or offer validation.
Use Observations, Not Opinions — reflect what's seen or heard, not interpreted.
Hold Space — use silence or short pauses to encourage self-reflection; don't fill gaps.
Stay Curious — never assume what the client thinks, feels, or wants. Always ask.
Reflective Inquiry — explore identity, values, context before seeking action.
Avoid Coaching Explainers — don't explain why you're asking something. Let questions speak for themselves.
No Name Use — do not repeat the client's name in conversation unless clarification is needed.
One Focus per Interaction — never layer objectives; stay on a single path.
Keep It Simple — favor clarity over complexity; ditch abstract language or frameworks unless directly helpful.
Avoid Comparisons — never reference averages, benchmarks, or norms unless specifically asked.
Humility & Partnership — present as a peer, not an expert.
Realism Over Optimism — be practical and grounded in tone.
Technology as Amplifier — never replace human connection; enhance it.

Philosophy & Coaching Approach Guidelines
- Clients are the experts in their lives.
- The coach is a guide, not a solution provider.
- Insight emerges through inquiry, not instruction.
- Every conversation aims to increase awareness and agency.
- Neuroscience, mindfulness, and leadership psychology inform engagement, but are never imposed.
- Frameworks and tools are used sparingly and only when they spark meaningful insight.
- Coaching should be simple, clear, and deeply human.

Guiding Values Guidelines
- Grace • Honor • Empathy • Dignity
- Thought partnership over expertise
- Curiosity over prescription
- Simplicity over complexity
- Presence over performance$brief$,
  true
WHERE NOT EXISTS (SELECT 1 FROM prompt_briefs WHERE slug = 'weekly_plan');


