-- ==================== 067_coach_tasks.sql ====================
-- Migration 067 — coach attention queue, session-note close-out, cron run log
-- Procedure: docs/MIGRATION_PROCEDURE.md  (snapshot → staging → verify → prod)
-- Applied to PRODUCTION WITHOUT STAGING under a logged exception (staging is
-- paused; the change is additive only) — see APP_STATE.md.
--
--  1. coach_tasks — a generic per-coach task queue ("Needs Your Attention").
--     v1 populates it with session-note tasks only (subject_type
--     'session_note', task_type 'write_note' | 'send_note'), but subject_type
--     and task_type are deliberately UNCONSTRAINED text so unmatched bookings,
--     billing review, and nudge approvals can be added later with no migration.
--     States: pending | sent | filed | dismissed (no snooze). The partial unique
--     index is the idempotency guard — a cron re-run cannot double-create a
--     pending task for the same appointment + type.
--     Isolation is application code: every query filters by coach_id.
--
--  2. cron_runs — the reviewable failure queue for every Vercel cron. One row
--     per run (running → ok | failed) with a summary and the error text, so a
--     job that dies leaves evidence. Platform-wide (all seven crons write it),
--     not tenant data; org_id is carried for schema uniformity only.
--
--  3. notes — session-note close-out columns. status is a VIEW FILTER ONLY:
--     the prep engine, nudge pipeline, scorecard and every aggregate keep
--     reading notes of all statuses; a sent note is hidden in the workspace UI
--     only. Sent-state truth stays on the 050 columns (sent_to_client_at,
--     client_communication_id) — code treats a note as sent when EITHER
--     status = 'sent' OR sent_to_client_at IS NOT NULL, so no backfill is
--     needed and pre-067 sends stay correct.
--
--  4. coaches — daily digest settings (hour in the coach's timezone, on/off)
--     and the once-a-day idempotency stamp.
--
-- All additive (one new table + one log table + defaulted/nullable columns, no
-- drops, no type changes, no row backfill). Reversible via
-- 067_coach_tasks_down.sql.

-- 1. coach_tasks ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS coach_tasks (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                     REFERENCES organizations(id),
  coach_id         uuid NOT NULL REFERENCES coaches(id) ON DELETE CASCADE,
  client_id        uuid REFERENCES clients(id) ON DELETE CASCADE,
  appointment_id   uuid REFERENCES appointments(id) ON DELETE CASCADE,
  subject_type     text NOT NULL DEFAULT 'session_note',   -- extensible
  task_type        text NOT NULL,                          -- 'write_note' | 'send_note' (extensible)
  state            text NOT NULL DEFAULT 'pending',        -- 'pending' | 'sent' | 'filed' | 'dismissed'
  due_at           timestamptz NOT NULL,
  resolved_at      timestamptz,
  resolved_by      uuid REFERENCES coaches(id),            -- NULL = resolved by the system (cron reconcile)
  resolution_note  text,
  digest_count     int NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

-- Idempotency guard: at most ONE pending task per (coach, appointment, type).
CREATE UNIQUE INDEX IF NOT EXISTS coach_tasks_pending_once_idx
  ON coach_tasks (coach_id, appointment_id, task_type)
  WHERE state = 'pending';
CREATE INDEX IF NOT EXISTS coach_tasks_coach_state_due_idx
  ON coach_tasks (coach_id, state, due_at);
CREATE INDEX IF NOT EXISTS coach_tasks_appointment_idx ON coach_tasks (appointment_id);
CREATE INDEX IF NOT EXISTS coach_tasks_org_id_idx ON coach_tasks (org_id);

DROP TRIGGER IF EXISTS coach_tasks_set_updated_at ON coach_tasks;
CREATE TRIGGER coach_tasks_set_updated_at
  BEFORE UPDATE ON coach_tasks
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

ALTER TABLE coach_tasks ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE coach_tasks IS
  'Per-coach attention queue. v1: session-note tasks. subject_type/task_type are open text so new task kinds need no migration. Scoped by coach_id in application code.';

-- 2. cron_runs --------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cron_runs (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001'
                 REFERENCES organizations(id),
  job          text NOT NULL,                       -- 'reminders' | 'coach-tasks' | 'coach-digest' | ...
  status       text NOT NULL DEFAULT 'running',     -- 'running' | 'ok' | 'failed'
  started_at   timestamptz NOT NULL DEFAULT now(),
  finished_at  timestamptz,
  summary      jsonb,
  error        text
);
CREATE INDEX IF NOT EXISTS cron_runs_job_started_idx ON cron_runs (job, started_at DESC);
CREATE INDEX IF NOT EXISTS cron_runs_failed_idx
  ON cron_runs (started_at DESC) WHERE status <> 'ok';
ALTER TABLE cron_runs ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE cron_runs IS
  'One row per cron run (running → ok | failed). The reviewable failure queue: a job that dies must leave evidence.';

-- 3. notes — close-out columns (status is a VIEW filter only) ----------------
ALTER TABLE notes ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'draft';
ALTER TABLE notes ADD COLUMN IF NOT EXISTS generated_narrative text;
ALTER TABLE notes ADD COLUMN IF NOT EXISTS narrative_generated_at timestamptz;
ALTER TABLE notes ADD COLUMN IF NOT EXISTS filed_at timestamptz;
ALTER TABLE notes ADD COLUMN IF NOT EXISTS reopened_at timestamptz;
ALTER TABLE notes ADD COLUMN IF NOT EXISTS reopen_count int NOT NULL DEFAULT 0;

COMMENT ON COLUMN notes.status IS
  'draft | sent | filed. VIEW FILTER ONLY — never filter data consumers (prep, nudges, scoring, aggregates) on it. Sent truth = sent_to_client_at (050); code reads sent as status=sent OR sent_to_client_at IS NOT NULL.';
COMMENT ON COLUMN notes.generated_narrative IS
  'Cached Claude client-narrative draft for the send flow; generated once, edited by the coach, never regenerated on reopen.';

-- 4. coaches — digest settings ---------------------------------------------
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS digest_hour int NOT NULL DEFAULT 17;
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS digest_enabled boolean NOT NULL DEFAULT true;
ALTER TABLE coaches ADD COLUMN IF NOT EXISTS last_digest_sent_on date;

ALTER TABLE coaches DROP CONSTRAINT IF EXISTS coaches_digest_hour_range;
ALTER TABLE coaches ADD CONSTRAINT coaches_digest_hour_range CHECK (digest_hour BETWEEN 0 AND 23);

COMMENT ON COLUMN coaches.digest_hour IS
  'Local hour (0-23, coaches.timezone) the daily Needs-Your-Attention digest is sent. Default 17.';
COMMENT ON COLUMN coaches.last_digest_sent_on IS
  'Coach-local date of the last digest actually sent (idempotency). Not updated when there was nothing to send.';

NOTIFY pgrst, 'reload schema';


-- ==================== 068_note_send_claim.sql ====================
-- Migration 068 — session-note send claim (claim-before-send + idempotency key)
-- Procedure: docs/MIGRATION_PROCEDURE.md  (snapshot → staging → verify → prod)
-- Same additive-only shape as 067; same logged staging exception applies.
--
-- The Phase 3 send flow must produce exactly ONE email and ONE communications
-- row for a note even when the coach double-taps Send or has the editor open
-- in two tabs. The billing charge path solved this with a claim row +
-- idempotency key; notes get the same pattern on the row itself:
--
--   send_attempt          monotonically increasing attempt counter. The claim
--                         is a compare-and-set: UPDATE … WHERE send_attempt =
--                         <the value the request read> AND sent_to_client_at
--                         IS NULL AND (send_claimed_at IS NULL OR stale) —
--                         two concurrent requests read the same value, so at
--                         most one UPDATE matches.
--   send_claimed_at       set at claim, cleared on failure. A claim older than
--                         3 minutes is treated as stale (the function died
--                         mid-send) and may be re-claimed.
--   send_idempotency_key  'note:<id>:<attempt>' — recorded on the note and on
--                         the communications row so any duplicate is auditable.
--
-- Additive, defaulted/nullable, no backfill. Reversible via
-- 068_note_send_claim_down.sql.

ALTER TABLE notes ADD COLUMN IF NOT EXISTS send_attempt int NOT NULL DEFAULT 0;
ALTER TABLE notes ADD COLUMN IF NOT EXISTS send_claimed_at timestamptz;
ALTER TABLE notes ADD COLUMN IF NOT EXISTS send_idempotency_key text;

COMMENT ON COLUMN notes.send_attempt IS
  'Send-claim CAS counter (068). Each send claim increments it; the claim UPDATE matches only the value the request read.';
COMMENT ON COLUMN notes.send_claimed_at IS
  'Set while a send is in flight; cleared on failure. Older than 3 min = stale claim, may be re-claimed.';

NOTIFY pgrst, 'reload schema';


-- ==================== 069_ai_cost_controls.sql ====================
-- Migration 069 — AI cost controls: model prices, usage ledger, budgets
-- Procedure: docs/MIGRATION_PROCEDURE.md  (snapshot → staging → verify → prod)
-- Additive only (three new tables, seed rows, no changes to existing tables) —
-- the same logged staging exception as 067/068 applies.
--
-- Brief: "AI Cost Controls, Model Routing & Context Budgeting", Phase 1.
-- Every Anthropic call now goes through ONE gateway (lib/ai/client.ts) which
-- writes a row here BEFORE the call (status 'reserved', worst-case cost) and
-- settles it with the response's real token usage AFTER ('settled'), or marks
-- it 'released' on error. Money is stored as integer USD micros (1 USD =
-- 1,000,000) — never floats. Prices are DATA (ai_model_prices), not code.
--
--   ai_model_prices  per-model list prices, per million tokens, in micros;
--                    the newest effective_from ≤ today wins. Seeded from
--                    platform.claude.com/docs/en/about-claude/pricing (2026-09-18).
--   ai_usage         the ledger — one row per Anthropic request, tenant-scoped
--                    (org_id / coach_id / client_id), tagged with the routing
--                    purpose + the calling feature + who the call was for
--                    (principal). request_id is the idempotency key.
--   ai_budgets       caps per scope. Phase 1 seeds the brief's defaults with
--                    enabled = false; Phase 2 turns enforcement on. period_month
--                    NULL = a standing default for every month; a dated row
--                    overrides that month only (how "Extend this month" works).
--
-- Reversible via 069_ai_cost_controls_down.sql (drops the ledger).

-- ---------------------------------------------------------------------------
-- ai_model_prices
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_model_prices (
  id                          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  model                       text NOT NULL,
  -- USD micros per 1,000,000 tokens (so $5.00/MTok = 5000000).
  input_per_mtok_micros       bigint NOT NULL CHECK (input_per_mtok_micros >= 0),
  output_per_mtok_micros      bigint NOT NULL CHECK (output_per_mtok_micros >= 0),
  cache_read_per_mtok_micros  bigint NOT NULL CHECK (cache_read_per_mtok_micros >= 0),
  -- 5-minute cache write (1.25× input). The 1h write (2×) is not used by the app.
  cache_write_per_mtok_micros bigint NOT NULL CHECK (cache_write_per_mtok_micros >= 0),
  effective_from              date NOT NULL DEFAULT current_date,
  source                      text,
  created_at                  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (model, effective_from)
);
ALTER TABLE ai_model_prices ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE ai_model_prices IS
  'AI list prices per model, USD micros per million tokens (069). Newest effective_from <= today wins.';

INSERT INTO ai_model_prices
  (model, input_per_mtok_micros, output_per_mtok_micros, cache_read_per_mtok_micros, cache_write_per_mtok_micros, effective_from, source)
VALUES
  ('claude-opus-5',              5000000, 25000000, 500000, 6250000, '2026-09-18', 'platform.claude.com/docs/en/about-claude/pricing 2026-09-18'),
  ('claude-sonnet-5',            2000000, 10000000, 200000, 2500000, '2026-09-18', 'platform.claude.com/docs/en/about-claude/pricing 2026-09-18'),
  ('claude-haiku-4-5-20251001',  1000000,  5000000, 100000, 1250000, '2026-09-18', 'platform.claude.com/docs/en/about-claude/pricing 2026-09-18'),
  ('claude-haiku-4-5',           1000000,  5000000, 100000, 1250000, '2026-09-18', 'alias of claude-haiku-4-5-20251001'),
  ('claude-sonnet-4-6',          3000000, 15000000, 300000, 3750000, '2026-09-18', 'platform.claude.com/docs/en/about-claude/pricing 2026-09-18'),
  ('claude-opus-4-8',            5000000, 25000000, 500000, 6250000, '2026-09-18', 'platform.claude.com/docs/en/about-claude/pricing 2026-09-18')
ON CONFLICT (model, effective_from) DO NOTHING;

-- ---------------------------------------------------------------------------
-- ai_usage — the ledger
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_usage (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id          text NOT NULL UNIQUE,
  org_id              uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001' REFERENCES organizations(id),
  coach_id            uuid REFERENCES coaches(id) ON DELETE SET NULL,
  client_id           uuid REFERENCES clients(id) ON DELETE SET NULL,
  principal           text NOT NULL CHECK (principal IN ('coach', 'client', 'system')),
  -- purpose = the routing key in lib/ai/models.ts (what decides the model);
  -- feature = the caller's finer label (e.g. 'portal_chat:general', 'scoring:rescore').
  purpose             text NOT NULL,
  feature             text NOT NULL,
  model               text NOT NULL,
  status              text NOT NULL DEFAULT 'reserved' CHECK (status IN ('reserved', 'settled', 'released')),
  reserved_usd_micros bigint NOT NULL DEFAULT 0,
  input_tokens        integer,
  output_tokens       integer,
  cache_read_tokens   integer,
  cache_write_tokens  integer,
  actual_usd_micros   bigint,
  stop_reason         text,
  error               text,
  duration_ms         integer,
  -- free-form: effort, streamed, price_missing, estimated_input_tokens; Phase 3 adds slice sizes.
  metadata            jsonb,
  created_at          timestamptz NOT NULL DEFAULT now(),
  settled_at          timestamptz
);
ALTER TABLE ai_usage ENABLE ROW LEVEL SECURITY;
CREATE INDEX IF NOT EXISTS ai_usage_org_created_idx    ON ai_usage (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ai_usage_client_created_idx ON ai_usage (client_id, created_at DESC) WHERE client_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ai_usage_coach_created_idx  ON ai_usage (coach_id, created_at DESC) WHERE coach_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ai_usage_feature_created_idx ON ai_usage (org_id, feature, created_at DESC);
-- The stale-reservation sweep (Phase 2) and the budget check read only open rows.
CREATE INDEX IF NOT EXISTS ai_usage_reserved_idx       ON ai_usage (created_at) WHERE status = 'reserved';
COMMENT ON TABLE ai_usage IS
  'AI usage ledger (069): one row per Anthropic request. reserved (worst case, before the call) -> settled (actual usage) | released (error). USD micros.';

-- ---------------------------------------------------------------------------
-- ai_budgets
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_budgets (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id         uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001' REFERENCES organizations(id),
  scope          text NOT NULL CHECK (scope IN ('org', 'client', 'feature')),
  -- org:     the org id (the client-principal ceiling)
  -- client:  a client uuid, or 'default' / 'default:<client_type>' (e.g. 'default:portal')
  -- feature: a purpose name from lib/ai/models.ts, or a family ('coach')
  scope_id       text NOT NULL,
  -- first day of the month this row applies to; NULL = standing default for every month
  period_month   date CHECK (period_month IS NULL OR period_month = date_trunc('month', period_month)::date),
  cap_usd_micros bigint NOT NULL CHECK (cap_usd_micros >= 0),
  soft_pct       integer NOT NULL DEFAULT 80 CHECK (soft_pct BETWEEN 0 AND 100),
  enabled        boolean NOT NULL DEFAULT false,
  note           text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE ai_budgets ENABLE ROW LEVEL SECURITY;
-- One row per (org, scope, scope_id, month); NULL months collapse onto one sentinel.
CREATE UNIQUE INDEX IF NOT EXISTS ai_budgets_scope_period_uidx
  ON ai_budgets (org_id, scope, scope_id, COALESCE(period_month, '1970-01-01'::date));
COMMENT ON TABLE ai_budgets IS
  'AI spend caps per scope (069). enabled=false rows are documentation only; Phase 2 enforces enabled rows. USD micros.';

-- Brief defaults, enforcement OFF until Phase 2 (and until Jeff confirms the numbers):
--   org portal ceiling $500/month · per-client $10/month · ZF/portal participant $3/month
INSERT INTO ai_budgets (org_id, scope, scope_id, period_month, cap_usd_micros, soft_pct, enabled, note) VALUES
  ('00000000-0000-4000-8000-000000000001', 'org',    '00000000-0000-4000-8000-000000000001', NULL, 500000000, 80, false, 'Org ceiling for all client-principal (portal) calls — brief default $500/month'),
  ('00000000-0000-4000-8000-000000000001', 'client', 'default',                              NULL,  10000000, 80, false, 'Per-client portal cap — brief default $10/month'),
  ('00000000-0000-4000-8000-000000000001', 'client', 'default:portal',                       NULL,   3000000, 80, false, 'ZF 360 participant cap (client_type = portal) — brief default $3/month')
ON CONFLICT DO NOTHING;

NOTIFY pgrst, 'reload schema';


-- ==================== 070_ai_budget_enforcement.sql ====================
-- Migration 070 — AI budget enforcement: atomic reserve, status, stale release, alerts
-- Procedure: docs/MIGRATION_PROCEDURE.md  (snapshot → staging → verify → prod)
-- Additive (four functions + one table + enabling the seeded caps) — same
-- logged staging exception as 067–069.
--
-- Brief: "AI Cost Controls, Model Routing & Context Budgeting", Phase 2.
-- The gateway (lib/ai/client.ts) no longer inserts the ledger row itself: it
-- calls ai_reserve(), which — inside ONE transaction, under a per-org advisory
-- lock — sums the month's spend for every scope the call falls under
-- (client · org · feature), refuses if spend + worst case would exceed an
-- enabled cap, and otherwise inserts the 'reserved' row. Two concurrent
-- requests at a nearly-exhausted cap therefore cannot both pass: the second
-- sees the first's reservation. No AI in this math.
--
--   ai_resolve_cap    first enabled cap for a scope: a row dated THIS month
--                     wins over the standing (NULL-month) row; scope_ids are
--                     tried in order (client id → 'default:<client_type>' →
--                     'default'; purpose → 'principal:<principal>').
--   ai_month_spend    Σ coalesce(actual, reserved) over reserved+settled rows
--                     in the UTC month for one scope.
--   ai_reserve        the atomic check-and-insert (returns jsonb).
--   ai_budget_status  read-only view of the same numbers (soft/hard state,
--                     reset date) for the gateway's pre-check, the coach's
--                     workspace card, and the Phase 4 cockpit.
--   ai_release_stale  releases 'reserved' rows older than N minutes (a
--                     function killed mid-call) — run hourly by /api/cron/ai-budget.
--   ai_alerts         claim-before-send ledger for the 50/80/100 % org emails
--                     and the per-client soft/hard notices (unique per period).
--
-- Also ENABLES the three caps 069 seeded (org $500 · client $10 · portal
-- participant $3) — Jeff's "go" on the brief defaults, 2026-09-19.
-- Reversible via 070_ai_budget_enforcement_down.sql.

-- ---------------------------------------------------------------------------
-- ai_alerts — claim-before-send
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_alerts (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL DEFAULT '00000000-0000-4000-8000-000000000001' REFERENCES organizations(id),
  kind         text NOT NULL CHECK (kind IN ('org_threshold', 'client_soft', 'client_hard')),
  scope_id     text NOT NULL,
  period_month date NOT NULL,
  threshold    integer NOT NULL DEFAULT 0,
  detail       jsonb,
  created_at   timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE ai_alerts ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX IF NOT EXISTS ai_alerts_claim_uidx ON ai_alerts (org_id, kind, scope_id, period_month, threshold);
COMMENT ON TABLE ai_alerts IS 'AI spend alert claims (070): one row per (kind, scope, month, threshold); insert before sending so an alert can never double-send.';

-- ---------------------------------------------------------------------------
-- ai_resolve_cap
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ai_resolve_cap(p_org_id uuid, p_scope text, p_scope_ids text[], p_period date)
RETURNS TABLE (cap_usd_micros bigint, soft_pct integer, scope_id text)
LANGUAGE plpgsql STABLE AS $$
DECLARE
  sid text;
BEGIN
  FOREACH sid IN ARRAY p_scope_ids LOOP
    CONTINUE WHEN sid IS NULL;
    RETURN QUERY
      SELECT b.cap_usd_micros, b.soft_pct, b.scope_id
        FROM ai_budgets b
       WHERE b.org_id = p_org_id AND b.scope = p_scope AND b.scope_id = sid AND b.enabled
         AND (b.period_month = p_period OR b.period_month IS NULL)
       ORDER BY b.period_month DESC NULLS LAST
       LIMIT 1;
    IF FOUND THEN RETURN; END IF;
  END LOOP;
  RETURN;
END $$;

-- ---------------------------------------------------------------------------
-- ai_month_spend — reserved + settled, worst case where not yet settled
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ai_month_spend(p_org_id uuid, p_scope text, p_scope_id text, p_period date)
RETURNS bigint
LANGUAGE sql STABLE AS $$
  SELECT COALESCE(SUM(COALESCE(u.actual_usd_micros, u.reserved_usd_micros)), 0)::bigint
    FROM ai_usage u
   WHERE u.org_id = p_org_id
     AND u.status IN ('reserved', 'settled')
     AND u.created_at >= (p_period::timestamp AT TIME ZONE 'utc')
     AND u.created_at <  ((p_period + interval '1 month')::timestamp AT TIME ZONE 'utc')
     AND CASE p_scope
           WHEN 'client'  THEN u.principal = 'client' AND u.client_id::text = p_scope_id
           WHEN 'org'     THEN u.principal = 'client'
           WHEN 'feature' THEN u.purpose = p_scope_id
           ELSE false
         END;
$$;

-- ---------------------------------------------------------------------------
-- ai_reserve — atomic check-and-insert
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ai_reserve(
  p_request_id text, p_org_id uuid, p_coach_id uuid, p_client_id uuid, p_principal text,
  p_purpose text, p_feature text, p_model text, p_reserved bigint, p_metadata jsonb
) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v_period  date := date_trunc('month', now() AT TIME ZONE 'utc')::date;
  v_resets  date := (date_trunc('month', now() AT TIME ZONE 'utc') + interval '1 month')::date;
  v_ctype   text;
  v_cap     record;
  v_spent   bigint;
  v_id      uuid;
BEGIN
  -- One lock per org: every reserve in the org is serialized, so the sums below
  -- always include every earlier reservation. Cheap at this scale.
  PERFORM pg_advisory_xact_lock(hashtext('ai_reserve:' || p_org_id::text));

  IF p_principal = 'client' AND p_client_id IS NOT NULL THEN
    SELECT c.client_type INTO v_ctype FROM clients c WHERE c.id = p_client_id;
    SELECT * INTO v_cap FROM ai_resolve_cap(p_org_id, 'client', ARRAY[p_client_id::text, 'default:' || COALESCE(v_ctype, 'client'), 'default'], v_period);
    IF v_cap.cap_usd_micros IS NOT NULL THEN
      v_spent := ai_month_spend(p_org_id, 'client', p_client_id::text, v_period);
      IF v_spent + p_reserved > v_cap.cap_usd_micros THEN
        RETURN jsonb_build_object('ok', false, 'scope', 'client', 'cap', v_cap.cap_usd_micros, 'spent', v_spent, 'reserved', p_reserved, 'resets_on', v_resets);
      END IF;
    END IF;

    SELECT * INTO v_cap FROM ai_resolve_cap(p_org_id, 'org', ARRAY[p_org_id::text], v_period);
    IF v_cap.cap_usd_micros IS NOT NULL THEN
      v_spent := ai_month_spend(p_org_id, 'org', p_org_id::text, v_period);
      IF v_spent + p_reserved > v_cap.cap_usd_micros THEN
        RETURN jsonb_build_object('ok', false, 'scope', 'org', 'cap', v_cap.cap_usd_micros, 'spent', v_spent, 'reserved', p_reserved, 'resets_on', v_resets);
      END IF;
    END IF;
  END IF;

  SELECT * INTO v_cap FROM ai_resolve_cap(p_org_id, 'feature', ARRAY[p_purpose, 'principal:' || p_principal], v_period);
  IF v_cap.cap_usd_micros IS NOT NULL THEN
    v_spent := ai_month_spend(p_org_id, 'feature', p_purpose, v_period);
    IF v_spent + p_reserved > v_cap.cap_usd_micros THEN
      RETURN jsonb_build_object('ok', false, 'scope', 'feature', 'cap', v_cap.cap_usd_micros, 'spent', v_spent, 'reserved', p_reserved, 'resets_on', v_resets);
    END IF;
  END IF;

  INSERT INTO ai_usage (request_id, org_id, coach_id, client_id, principal, purpose, feature, model, status, reserved_usd_micros, metadata)
  VALUES (p_request_id, p_org_id, p_coach_id, p_client_id, p_principal, p_purpose, p_feature, p_model, 'reserved', p_reserved, p_metadata)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END $$;

-- ---------------------------------------------------------------------------
-- ai_budget_status — the same numbers, read-only
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ai_budget_status(p_org_id uuid, p_client_id uuid, p_principal text, p_purpose text)
RETURNS jsonb
LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_period date := date_trunc('month', now() AT TIME ZONE 'utc')::date;
  v_resets date := (date_trunc('month', now() AT TIME ZONE 'utc') + interval '1 month')::date;
  v_ctype  text;
  v_cap    record;
  v_spent  bigint;
  v_client jsonb := NULL;
  v_org    jsonb := NULL;
  v_feat   jsonb := NULL;
  v_state  text := 'ok';
BEGIN
  IF p_client_id IS NOT NULL THEN
    SELECT c.client_type INTO v_ctype FROM clients c WHERE c.id = p_client_id;
    SELECT * INTO v_cap FROM ai_resolve_cap(p_org_id, 'client', ARRAY[p_client_id::text, 'default:' || COALESCE(v_ctype, 'client'), 'default'], v_period);
    v_spent := ai_month_spend(p_org_id, 'client', p_client_id::text, v_period);
    v_client := jsonb_build_object('spent', v_spent, 'cap', v_cap.cap_usd_micros, 'soft_pct', v_cap.soft_pct, 'source', v_cap.scope_id);
    IF v_cap.cap_usd_micros IS NOT NULL THEN
      IF v_spent >= v_cap.cap_usd_micros THEN v_state := 'hard';
      ELSIF v_spent * 100 >= v_cap.cap_usd_micros * v_cap.soft_pct THEN v_state := 'soft';
      END IF;
    END IF;
  END IF;

  SELECT * INTO v_cap FROM ai_resolve_cap(p_org_id, 'org', ARRAY[p_org_id::text], v_period);
  v_spent := ai_month_spend(p_org_id, 'org', p_org_id::text, v_period);
  v_org := jsonb_build_object('spent', v_spent, 'cap', v_cap.cap_usd_micros, 'soft_pct', v_cap.soft_pct);
  IF p_principal = 'client' AND v_cap.cap_usd_micros IS NOT NULL AND v_spent >= v_cap.cap_usd_micros THEN v_state := 'hard'; END IF;

  IF p_purpose IS NOT NULL THEN
    SELECT * INTO v_cap FROM ai_resolve_cap(p_org_id, 'feature', ARRAY[p_purpose, 'principal:' || COALESCE(p_principal, 'system')], v_period);
    v_spent := ai_month_spend(p_org_id, 'feature', p_purpose, v_period);
    v_feat := jsonb_build_object('spent', v_spent, 'cap', v_cap.cap_usd_micros, 'soft_pct', v_cap.soft_pct);
    IF v_cap.cap_usd_micros IS NOT NULL AND v_spent >= v_cap.cap_usd_micros THEN v_state := 'hard'; END IF;
  END IF;

  RETURN jsonb_build_object('state', v_state, 'period_month', v_period, 'resets_on', v_resets, 'client', v_client, 'org', v_org, 'feature', v_feat);
END $$;

-- ---------------------------------------------------------------------------
-- ai_release_stale — a reservation older than N minutes is a dead call
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ai_release_stale(p_minutes integer DEFAULT 15)
RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  UPDATE ai_usage
     SET status = 'released', error = 'stale reservation released by cron', settled_at = now()
   WHERE status = 'reserved' AND created_at < now() - make_interval(mins => p_minutes);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- ---------------------------------------------------------------------------
-- Enforcement ON for the seeded defaults (Jeff, 2026-09-19)
-- ---------------------------------------------------------------------------
UPDATE ai_budgets SET enabled = true, updated_at = now()
 WHERE period_month IS NULL AND note LIKE '%brief default%';

NOTIFY pgrst, 'reload schema';


-- ==================== 071_portal_history_summary.sql ====================
-- Migration 071 — portal conversation history summary (context budgeter, Phase 3)
-- Procedure: docs/MIGRATION_PROCEDURE.md  (snapshot → staging → verify → prod)
-- Additive, nullable/defaulted — same logged staging exception as 067–070.
--
-- The portal chat now sends only the last few turns verbatim (lib/ai/
-- context-budget.ts, HISTORY budget); older turns are replaced by a short
-- summary written by the cheapest model. The summary is stored on the thread
-- so it is written once per batch of older turns, not on every message:
--   history_summary          the running summary text
--   history_summary_through  how many of the thread's messages (oldest first)
--                            it covers; messages beyond it are verbatim
--   history_summary_at       when it was last written
-- Reads are defensive (pre-071 the chat drops older turns instead of
-- summarising them). Reversible via 071_portal_history_summary_down.sql.

ALTER TABLE portal_conversations ADD COLUMN IF NOT EXISTS history_summary text;
ALTER TABLE portal_conversations ADD COLUMN IF NOT EXISTS history_summary_through integer NOT NULL DEFAULT 0;
ALTER TABLE portal_conversations ADD COLUMN IF NOT EXISTS history_summary_at timestamptz;

COMMENT ON COLUMN portal_conversations.history_summary IS
  'Running summary of the turns older than the verbatim window (071); rides in the uncached tail of the chat prompt.';

NOTIFY pgrst, 'reload schema';


-- ==================== 072_publish_360_brief_v2_2.sql ====================
-- assessment_360: make the BRIEF BODY of rubrics/04_zf360_report_interpretation_rubric.md the active version
-- (re-activates an existing version with this body; else inserts the next version).
DO $do$
DECLARE
  o RECORD;
  match_version int;
  match_active boolean;
  next_version int;
BEGIN
  FOR o IN SELECT DISTINCT org_id FROM prompt_briefs UNION SELECT id FROM organizations LOOP
    SELECT version, is_active INTO match_version, match_active FROM prompt_briefs
      WHERE org_id = o.org_id AND slug = 'assessment_360' AND btrim(body) = btrim($brief$You are helping a leader make sense of their Extraordinary Leader 360 feedback report. They have already had a debrief with a human coach; you are a thinking partner for what comes next, not a first-contact interpreter breaking news. The structured data in this prompt is the report; you never saw the PDF. Every number is a perception — how a specific set of raters saw this person at a moment — never a measure of who they are.

The instrument, so you read it as it is built
- Nineteen competencies drawn as a tent: Character is the centre pole; Personal Capability, Focus on Results, Interpersonal Skills, and Leading Change are the corners. A tent-pole score is the average of its competencies.
- The Total Score of anything excludes the person's own Self rating. Overall Leadership Effectiveness is the average of every item.
- Two markers on every row: the 75th and 90th percentile of thousands of global leaders. Bands are percentile ranges, not score ranges — Profound Strength at or above the 90th; Promising Profound Strength 75th to 89th; Above Average 51st to 74th; Below Average 11th to 50th; Potential Fatal Flaw at or below the 10th. That is why a higher score can sit in a lower band. Give these mechanics only when they ask how a band is drawn.
- Rater groups with fewer than three responses (Manager excepted) are combined with another group; the data says how they were reported. Say so when it matters: "your direct reports were combined into Others, so that group includes them." Fewer than three direct reports means Employee Engagement is not reported — absent, not low.
- Importance: each rater, and the person, chose up to four competencies most important to success in the current role (some cast fewer). Passions: the person chose the six they most enjoy, regardless of how well they think they do them.
- Gap analysis: only the gaps the report marks are worth a sentence. Positive means others saw more than the person did; negative means the person rated themselves higher than others did. When no gap is marked, say it plainly: "you're seeing the perceptions of those around you accurately; you can trust your perception here."
- The report carries its own reading guide (Extraordinary Insights, Explore Your Report, the four-condition Fatal Flaw test, the Leadership Sweet Spot) and a Strength Builder guide. Both are in this prompt; cite them as Zenger Folkman's.

How to read the report with them (page order — the rankings page is the heart, the importance-and-passions page is where targets are chosen)
- Before any number: ask which voices they wish they had in the report, which voices they weight more heavily, and what makes that so.
- Overall page: name the group that saw the most and ask what makes it so; name the group that saw the least and ask what would make the biggest impact on how they are perceived as a leader. On a follow-up, open from the change instead: "there seems to be a shift — what accounts for it?", who saw less this time and "what made for this shift?", who saw more and "what are they seeing now that they didn't see last time?" If the Self rating moved, ask what changed in their self-perception. A guideline, not a rule.
- Engagement: one question at most — what keeps their people engaged now, and which of the six areas would make the biggest difference for their team. Never name its band. A movement between administrations may be named as a comparison; soften a small one ("a little higher this year").
- The tent is orientation. Name the pole closest to extraordinary and ask what contributes; on a low tent, still call the highest pole "a strong area" and ask what might nudge it toward the 75th, and ask which pole could be a general area of focus. Never dwell on the lowest pole, and never name the fatal-flaw band on the tent.
- Rankings: strengths first, always, even when nothing sits above Below Average. Name the two or three competencies closest to their own 90th-percentile mark (proximity is the distance to that mark, never the total score), in order, and ask "what about this is seen as strong by those around you?", "how have you been doing this so far?", "what might be some new ways?", "what would nudge it up to extraordinary in a way that makes a business difference?" Rank by band, then by score within a band, exactly as the report does; if they ask why a higher score ranks lower, explain the band against that competency's own 90th mark. A Below Average competency gets one clause ("low but not a fatal flaw") and is left. The lowest competency is named directly — with "what is your style here?" and "what have you seen good leaders do?" — only when it sits in the Potential Fatal Flaw band, and only after the higher-scoring areas have been talked about. When that band holds a competency, say so plainly: "a potential fatal flaw means it is perceived lower by many of your circle" — never define it by percentile — then park it for the targets page ("hold on to these; they come back there") and remind them the focus is strengths, not weaknesses.
- Behaviors: one question — "what stands out to you on this page?" Behaviors are fuel for a move once a development area is chosen: the lowest-scored items under a chosen competency say where to start.
- The targets page: introduce it through its three ideas — what you are good at, what you love, what the organisation needs. If "CPO" or "Sweet Spot" comes up (the report's own words for the page and the overlap), explain them once through those ideas. A potential target sits below its own 90th mark, was voted important by the people around them, and is a named passion. Those already at or above the 75th come first (the report's Leadership Sweet Spot); the 75th is not a floor — below it the same overlap is the report's Novice route ("could be built into a Profound Strength"), ordered by distance to the 75th. Point out potential targets with the reason for each circle in plain words ("it is a passion, it is almost a strength but not quite, the people around you weight it highly"), voiced as potential, never as a decision. Five potential focus areas at a time is the ideal; six is possible when they are all the overlaps there are. Name near-ties together rather than rank them. Rule a near competency out with its reason ("closest to a strength, but not a passion and few votes"). A target with no manager vote is something to be aware of, not a veto. Then: "if you were to focus on that this next season, how would you increase your score?", "what would you consider?", "what would be a rough goal you would set here?" The ultimate aim: three to five competencies above the 90th. With five or more Profound Strengths already, the report's own guide says to balance the tent — name the pole with the fewest and ask whether a target there would grow the whole tent. A competency in the fatal-flaw band is only noted here: without the organisation's votes it is not a fatal flaw for this role.
- Once they lean toward a target, name its Strength Builders — Zenger Folkman pairs each competency with companion behaviors to build around, not on — ask which builder they have real interest and passion for, and offer that builder's development ideas as raw material for a goal they write. Adapt, never assign.
- Gaps: when the report marks a gap where others saw more, ask "how might you reality check this?" When it marks one where they saw more, say "this is a potential blind spot" and, if they pick it to work on, suggest a few reality touch points to calibrate their perception. When every marked gap runs one way, name the pattern once ("your self-perception tends to run higher than those around you — how might that be affecting your scores?") and ask what tools they use to see their blind spots.
- Comments: read for themes across a section; tie a theme to the numbers where they agree, name it as a tension where they don't. Strengths and organisational-needs comments may be quoted sparingly. Potential-fatal-flaw comments are never quoted — itemize and summarize, and remind them the focus is getting to extraordinary and that flaws should be easy to see.
- "Do I have a fatal flaw?" is answered with the report's own four-condition test: the band, the organisation's importance votes, the lowest-scored behaviors, and the Potential Fatal Flaw comments. Walk the FATAL FLAW TEST block for each competency in the band and read the comments with them. A competency that fails any one condition is not a fatal flaw for this role. Never declare one on the band alone. When no competency sits in the band, say so, and treat a comment theme as a theme to hold, not a verdict. Keep it calm, and keep the route to a person open.
- The stock question when the next one is not obvious: "What do you think it would take to nudge this score up?"
- If the report reaches you only as a document's text rather than as structured data, say so and suggest they add it as their 360 report so all of it can be read.

Change between two reports (only when a comparison or reassessment block is present)
- Lead with band movement and the change in distance to the 90th; raw score deltas second. The first time change comes up, say what makes the two reports comparable or not (different raters, different norms, time elapsed) and ask about context before treating movement as personal change. Where the report marks a movement meaningful, say it with "it looks like" ("it looks like you made real progress on these three — how do you account for that?"), never as a flat assertion; where it does not, do not call it movement. Celebrate marked growth and ask what caused it; it is rarely where a goal comes from. Never total or rank the deltas, never produce a most-improved list, never credit coaching. An apparent decline gets care: not explained away, not minimised, and a person offered. The reassessment table itself needs no question of its own once the shift has been asked about on the overall page.
- A follow-up report carries its own comparison (the reassessment block): the same rules apply. Its direction is the report's own classification — a gap is meaningful only where the report colours it so (about .30 or more); never call a smaller movement meaningful. Name its rating windows and previous rater counts as the caveats. Only the previous totals it prints are known: no previous bands, norms, behaviors, or comments unless a comparison block also supplies them.
- With no prior report on file and no reassessment block, say so, and say what a comparison would show if a later report arrives.

Conversation moves
- Reflect what they said, then ask one question. One question per turn; a page gets one to three questions at most, and engagement, the tent, the reassessment table and the behaviors pages get one.
- Perception language throughout: what raters saw, never what the person is. "Your peers saw this as a standout", never "you are strong at this". Never call out a low score; the fatal-flaw band is the only exception, and it comes later, never first.
- When they ask what their goals should be, point out the potential targets with their reasons and ask back — even on the third ask. The client is the ultimate decider. Offer "Save as a goal" only once they have said, in their own words, what they want.
- If they ask for numbers, quote them exactly from the data with the band and the norms on that row. If it is not in the data, say you don't have it.
- Zenger Folkman's research claims (what the top 10% of leaders produce; strengths over fixing weaknesses) and its guides are theirs — say "Zenger Folkman's research finds" or "Zenger Folkman's guide pairs this with", never present them as settled science or as your own.

Never
- Never speculate about which individual, or which member of a rater group, wrote or scored anything, under any framing. Decline warmly and explain in one sentence that comments are anonymous within each group so people can be candid.
- Never mention weights, ranking logic, or the phrase "closest to green".
- Never use evaluative or diagnostic register: no "your weakness is", no "you should be concerned", no "you overrate yourself".
- Never treat a missing or collapsed section as a score.
- Never invent a score, a percentile, a norm, or a comment.
- Never quote a potential-fatal-flaw comment, name the fatal-flaw band on the tent or engagement, define a fatal flaw by percentile, declare one on the band alone, or name more than six potential focus areas.$brief$)
      ORDER BY version DESC LIMIT 1;
    IF match_version IS NOT NULL THEN
      IF NOT match_active THEN
        UPDATE prompt_briefs SET is_active = false
          WHERE org_id = o.org_id AND slug = 'assessment_360' AND is_active;
        UPDATE prompt_briefs SET is_active = true
          WHERE org_id = o.org_id AND slug = 'assessment_360' AND version = match_version;
      END IF;
      CONTINUE;
    END IF;
    SELECT COALESCE(MAX(version), 0) + 1 INTO next_version FROM prompt_briefs
      WHERE org_id = o.org_id AND slug = 'assessment_360';
    UPDATE prompt_briefs SET is_active = false
      WHERE org_id = o.org_id AND slug = 'assessment_360' AND is_active;
    INSERT INTO prompt_briefs (org_id, slug, version, title, body, is_active)
      VALUES (o.org_id, 'assessment_360', next_version, 'Assessment 360 interpretation brief v2.2 — Extraordinary Leader (calibrated on reports 5, 3, 4)', $brief$You are helping a leader make sense of their Extraordinary Leader 360 feedback report. They have already had a debrief with a human coach; you are a thinking partner for what comes next, not a first-contact interpreter breaking news. The structured data in this prompt is the report; you never saw the PDF. Every number is a perception — how a specific set of raters saw this person at a moment — never a measure of who they are.

